-- 0010_memory_book.sql
--
-- Книга пам'яті «Дідусі та онуки: спадковість поколінь» (2024 р.):
-- родичі вчителів та учнів ліцею — учасники Другої світової війни.
--
-- Записи перенесені з презентації ліцею; фотографії витягнуті з тієї ж
-- презентації та лежать у public/memory. Оригінальний файл презентації —
-- public/docs/knyha-pamyati-2024.pdf.
--
-- Додавати й редагувати записи може адміністрація або модератор
-- (сторінка /profile/memory у кабінеті).
--
-- Міграція безпечна для повторного запуску: наповнення виконується лише
-- тоді, коли таблиця порожня.

create table if not exists public.memory_entries (
  id           uuid primary key default gen_random_uuid(),
  name         text not null,
  relation     text,
  biography    text,
  photo_url    text,
  -- Сторінка вихідної презентації, з якої взято запис.
  source_page  int,
  sort_order   int not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index if not exists memory_entries_order_idx
  on public.memory_entries (sort_order);

alter table public.memory_entries enable row level security;

-- Читає будь-хто: книга пам'яті публічна.
drop policy if exists memory_entries_read on public.memory_entries;
create policy memory_entries_read
  on public.memory_entries for select using (true);

-- Пише лише адміністрація або модератор.
drop policy if exists memory_entries_manage on public.memory_entries;
create policy memory_entries_manage
  on public.memory_entries for all
  using (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid()
        and p.roles::text[] && array['owner', 'moderator']
    )
  )
  with check (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid()
        and p.roles::text[] && array['owner', 'moderator']
    )
  );

-- =====================================================================
-- Наповнення: 257 записів із презентації 2024 року
-- =====================================================================

insert into public.memory_entries (name, relation, biography, photo_url, source_page, sort_order)
select * from (values
  ('Мартиненко Петро Мойсейович', 'батько вчительки Рустамової Віри Петрівни', 'Військове звання – старшина. Призваний на військову службу 6 вересня 1939р., службу проходив на Далекому Сході. З червня 1941 року по травень 1945 року в складі 42 відділення 413 автотранспортного батальйону брав участь у боях. З серпня по вересень 1945 року брав участь у воєнних діях проти Японії. Демобілізований 6 червня 1946 року. Нагороджений Орденом Вітчизняної війни, медалями «За відвагу», «За перемогу над Японією».', '/memory/p002.jpg', 2, 0),
  ('Мартиненко Геннадій Мойсейович', 'дядько вчителя Рустамової Віри Петрівни', 'Призваний на військову службу у 1940 році. Воював з 1941 по 1944 рік. У 1944 році комісований через поранення. Нагороджений Орденом Вітчизняної війни, Орденом «За мужність», медаллю «За відвагу»', '/memory/p003.jpg', 3, 1),
  ('Чернецький Станіслав Віталійович', 'дідусь Махоткіної Анастасії', 'Народився 1 жовтня 1918 р. Був мобілізований до Червоної Армії ще студентом у 1941 році. Був артилеристом. Під час відступу зміг урятувати усю документацію канцелярії свого полка, за що отримав нагороду, яка знайшла його через 30 років після Перемоги. У 1943 отримав тяжке поранення. Помер 19 вересня 1999.', '/memory/p004.jpg', 4, 2),
  ('Кутовий Іван Васильович', 'дід вчительки Поліни Іванівни Трояновської', 'Учасник Другої Світової війни. Був активним членом Новомосковської підпільної організації з 1941 року, а з 1943 року її секретарем. Його дружина, Кутова Поліна Іванівна, також була членкинею Новомосковської підпільної організації. Підпільним комітетом були організовані диверсійні акти: мінування мостів, виведення із робочого режиму механізмів заводів; листівками закликали народ виявляти непокору нацистським загарбникам. В ніч з 17 на 18 серпня 1943 року майже всіх членів підпільної організації було заарештовано дніпропетровським гестапо. На допитах заарештованих жорстоко катували. Майже два місяці Іван Васильович провів у застінках гестапо. Пролунав вирок: «Страта. Розстріл. Спалення». У записці до дружини з катівень гестапо він писав: «Я не вмираю. Моє майбутнє – це моя дитина. Якщо син – то тільки Іван». За особисту мужність і відвагу у боях з ворогами країни під час Другої світової війни Поліна Іванівна Кутова та Іван Васильович Кутовий медаллю «За відвагу» нагороджені посмертно.', '/memory/p005.jpg', 5, 3),
  ('Усков Іван Павлович', 'дідусь вчительки математики ліцею Сагайдак Тетяни Василівни', 'Іван Павлович (1901 – 1957 рр.) з перших днів війни був на фронті. Дійшов до Берліна. Був поранений. Нагороджений медаллю «За перем́огу над Німе́ччиною»", чотирма медалями "За відвагу", подякою від Верховного Головнокомандувача.', '/memory/p006.jpg', 6, 4),
  ('Сагайдак Анатолій Данилович', 'свекор вчительки Сагайдак Тетяни Василівни', 'Сагайдак Анатолій Данилович (1927 - 2004 рр.) з 16 років пішов на фронт. Визволяв країни Європи та Німеччину від нацизму. Нагороджений багатьма медалями, у тому числі медаллю "За бойові заслуги".', '/memory/p007.jpg', 7, 5),
  ('Тимофєєв Михайло Іванович', 'дідусь Пономарьової Надії Анатоліївни', 'Михайло Іванович народився 18.05.1911р. у с.Юрга Томської обл. В армію був призваний наприкінці війни, у 1945 році, Юргінським РВК. На фронті був заряджаючим мінометної батареї 120мм мінометів. З характеристики у поданні до нагородження «Діючи у складі свого розрахунку, чіткою роботою сприяв знищенню живої сили і техніки противника». Отримав поранення. Був нагороджений медалями (назви не збереглися).', '/memory/p008.jpg', 8, 6),
  ('Пономарьов Дмитро Васильович', 'свекор Пономарьової Надії Анатоліївни', 'Дмитро Васильович народився 5 лютого 1911 у с. Панаторовське Нагорного р-ну Кіровської обл. В діючій армії з 22 червня 1941р. Пілот санітарного літака. Війну закінчив у званні гвардії капітана, командував 3-ю авіаційною ескадрильєю 87-го окремого гвардії авіаційного Сталінградського полку. За час війни здійснив понад 20 тис. вильотів, перевіз сотні поранених, лікарів та оперативних працівників, тони медикаментів, консервованої крові, інших військових вантажів. Авіаційна ланка, якою керував Пономарьов Д.В., літаючи в Карпатах, виконувала завдання з вивезення поранених у складних умовах з гірських аеродромів. У 1944 році готував для роботи в Карпатських горах льотчиків, які мали виконувати у важких умовах військові завдання. Ланка, керована Дмитром Васильовичем, було однією з передових в ескадрильї, завжди знаходилася у бойовій готовності. Нагороди: Орден Червоної Зірки, Орден Червоного Прапора, Орден Вітчизняної війни 1 та 2 ступенів, медалі "За бойові заслуги", "За оборону Сталінграда", "За перемогу над Німеччиною"', '/memory/p009.jpg', 9, 7),
  ('Шиян Микола Якович', 'дідусь вчительки Муринської Вікторії Вікторівни', 'Микола Якович народився 29 березня 1922 року в селі Березова Лука на Полтавщині в родині селян. Навчався в Миргородському керамічному технікумі. Коли почалась Друга світова війна, його було призвано до лав Червоної Армії. На початку війни він служив в 7-му учбовому автополку біля Сталінграду. Потім служив в 185 танковій бригаді. В 1943 році був направлений до 5-ї гвардійської дивізії командиром винищувальної протитанкової гармати. В листопаді 1944 року під містом Лібава (Латвія) Миколу Яковича було важко поранено (це було вже четверте поранення) і направлено до військового госпіталю. В госпіталі йому було ампутовано ногу. В жовтні 1945 року він був демобілізований з лав Червоної Армії. За бойові заслуги був нагороджений двома Орденами Червоної Зірки, орденом ВВВ та багатьма медалями. Він мав статус інваліда ВВВ. Після війни Микола Якович закінчив Київський політехнічний інститут, багато років працював на посаді директора Деревообробного комбінату в Києві. Микола Якович мав чудову сім’ю – дружину, сина та доньку; був дуже ерудованою та доброю людиною. Помер 9 липня 1984р., похований у Києві.', '/memory/p010.jpg', 10, 8),
  ('Муринський Михайло Михайлович', 'дідусь вчительки Муринської Вікторії Вікторівни', 'Михайло Михайлович народився 24 травня 1918 р. у селі Новотаволжанка, Шебекінського району, Бєлгородської області. Закінчив Томський політехнічний інститут. Під час Другої світової війни працював на гірничо – видобувних підприємствах Киргистану та Узбекистану, видобував вугілля для життєзабезпечення населення, а також рідкоземельні мінерали для потреб оборонної промисловості. З 1949 року працював в “Київметробуді”. Пройшов шлях від інженера до начальника тонельного загону. Михайло Михайлович мав звання “Учасника війни”, “Ветерана війни”, “Ветерана праці”, “Почесного метробудівця”. Був одружений, виховував 3 дітей. Нагороджений орденом “Знак пошани” та багатьма медалями. Помер 17 квітня 1998 р., похований в м. Києві.', '/memory/p011.jpg', 11, 9),
  ('Гусін Леонтій Олексійович', 'прадід Рогинської Євгенії', 'Леонтій Олексійович народився в березні 1918 року в м. Кривий Ріг Дніпропетровської обл. На початку війни був призваний Криворожським ГВК. У 1941 році потрапив в полон, але незабаром був звільнений радянськими військами. Після звільнення пройшов всю війну. Військове звання: рядовий, місце служби 49 стрілецький полк 50 стрілецької дивізії. У 1944 році був ранений, лікувався в евакуаційному госпіталі № 3435. Після війни працював вчителем математики. Помер в 1955 році в Криму.', '/memory/p012.jpg', 12, 10),
  ('Рогинський Давид Залманович', 'двоюрідний дід Рогинської Євгенії', 'Давід Залманович народився 11.08.1924 року. Був призваний на фронт Мікоянабадським РВК Таджицької РСР, Сталінабадської області 22.07.1942р. Мав військові звання: лейтенант; мл. лейтенант; ст. лейтенант. Служив у військових частинах: 1343 стрілецький полк 399 стрілецької дивізії,1312 стрілецький полк 17 стрілецької дивізії З військової характеристики: «При форсуванні річки Нарев 1 стрілецьким батальйоном у ніч з 21 на 22.09.1944 та заняття плацдарму в районі населеного пункту Хмелеве Варшавського воєводства тов.Рогинський, командуючи стрілецькою ротою, сміливо і рішуче без втрат разом із матеріальною частиною та боєприпасами, швидко та вміло зайняв вогневу позицію, чим забезпечив успішне форсування річки рештою підрозділів батальйону. У наступальному бою 14.10.1944 р. по прориву оборони противника та розширенню плацдарму Рогінський повів свою роту в атаку, чим сприяв успішному виконанню бойового завдання». Загинув 17 січня 1945 року на території Польщі. Місце поховання: Польща, Варшавське воєводство, пов. Макувський, д. Ляски, північно-західна околиця; Бишево, східна околиця, могила № 3, ряд 2, місце 2. Нагороджений орденом Вітчизняної війни II ступеня,', '/memory/p013.jpg', 13, 11),
  ('Чернюк Віктор Тихонович', 'прадід Євгенії Рогинської', 'Віктор Тихонович народився у вересні 1918 року в м. Києві. До воїнської служби був призваний ще 01.09.1937. Дата закінчення служби 21.08.1946р.. Служив в складі 43 гвардійського стрілецького полку 16 гвардійської стрілецької дивізії, 507 корпусному артилерійському полку. Мав військове звання лейтенант. Всю війну пройшов артилеристом i закінчив її в Берліні. Після війни до самої пенсії працював на Київському машинобудівному заводі ім. Артема', '/memory/p014.jpg', 14, 12),
  ('Наконечний Микола Ігнатович', 'прадідусь Грушевої Анастасії', 'Микола Ігнатович народився в 1919р. у с. М‘ясківка ( зараз - с. Городківка) Крижопільського р-ну Вінницької обл.. В рідному селі закінчив школу і залишився працювати в колгоспі. На початку війни пішов добровольцем на фронт. Загинув у березні 1944р., залишивши дружину з маленькою дитиною. Похований у братській могилі села Городівка (с. Крупське). На честь нього та ще одного невідомого солдата в його рідному селі було поставлено пам‘ятник.', '/memory/p015.jpg', 15, 13),
  ('Сідов Володимир Арсентійович', 'прадідусь Гусєвої Вероніки', 'Володимир Арсентійович народився 15 травня 1922р. у с. Старий Любар Любарського р-ну Житомирської обл. За спеціальністю був шофером 2 класу, спеціаліст колісних машин, механік. До війни працював у колгоспі водієм на молокозаводі. Під час війни був шофером автомеханічного полку, автоматником та кулеметником. Отримав поранення в голову, осколок залишився з ним до останніх днів життя. Був сміливим та безстрашним. В одному з боїв 02.08.1944р. з кулемету знищив приблизно взвод фашистів, не відійшов з зайнятого рубіжу, чим сприяв успішному відбиттю трьох контратак ворога. Нагороди: «Орден Вітчизняної війни 2 ступеня», чотири медалі «За відвагу», медаль «За перемогу над Німеччиною». Виховав п’ятьох дітей. Помер 19.02.2000р., похований в рідному селі.', '/memory/p016.jpg', 16, 14),
  ('Миколайко Павло Маркович', 'прадід Томків Дарини', 'Народився 1923 року в селі Буркачі Горохівського району Волинської області. Пішов на Фінську війну в 1943 році. Прослужив рік. Після повернення, отримав звання Ветеран війни зі всіма нагородами. Працював в Буркачах дорожником. Мав кохану дружину - Миколайко Олену та троїх дітей. Помер 1995 року в селі Буркачах.', '/memory/p017.jpg', 17, 15),
  ('Томків Андрій Григорович', 'прадід Томків Дарини', 'Андрій Григорович народився 1902 року в селі Якимові Кам''янсько- Буського району Львівської області. Воював у 1941-1944 роках. Після війни працював секретарем сільської ради, а потім бухгалтером колгоспу. Отримав звання «Ветеран війни» та мав орден «За заслуги». Мав люблячю жінку - Томків Марію Миколаївну та сімеро дітей. Помер 1993 року в селі Якимові, де і народився.', '/memory/p018.jpg', 18, 16),
  ('Томків Наталія Андріївна', 'сестра діда Томків Дарини', 'Наталія Андріївна народилась у 1928 року в селі Якимові Кам''янсько-Буського районі Львівської області. Ще будучі ученицею десятого класу вступила в УПА, де стала зв''язковою. Була арестованата засуджена. 10 років відбувала у сталінських таборах у Вуркоті. 1956 року була звільнена. Працювала в колгоспі, де була городницею. Посмертно нагороджена званням Героя України. Померла 2014 року в селі Якимові', '/memory/p019.jpg', 19, 17),
  ('Палиг Йосип Семенович', 'брат діда Томків Дарини', 'Народився 1923 року в селі Якимові Кам''янсько-Буського району Львівської області. Воював у 1944-1946 роках в рядах УПА, а в 1946 його забрали НКВД в Сталінські табори. Був засуджений на 25 років. Після звільнення жив в Якимові, працював в колгоспі. Посмертно присвоєно звання Героя України. Помер 1995 року в селі Якимові.', '/memory/p020.jpg', 20, 18),
  ('Піорко Володимир Антонович', null, 'Навчався у Литві на пілота 4 вересня 1939 його вертоліт було збито', null, 21, 19),
  ('Піорко Василь Антонович', null, 'Під час Другої Світової Війни його взяли у полон. Звідти він втік. Прибігши додому його сусіди здали фашистам, і його повісили на головній площіПід час Другої Світової Війни його взяли у полон. Звідти він втік. Прибігши додому його сусіди здали фашистам, і його повісили на головній площі', null, 22, 20),
  ('Декайло Іван Павлович', 'прадідусь Горбатюк-Бровенка Костянтина', 'Іван Павлович народився 17.02.1911р. на Слобожанщині, (тодішня Чернігівська губернія, Шосткинський повіт) На фронт пішов у 1942р. рядовим, був кулеметником. Визволяв Київ, форсував Дніпро в районі Лютізького плацдарму. Закінчив війну в 1945 р. під Берліном. Про війну ніколи не розповідав. Помер 5.10.1989. Похований у м. Києві', '/memory/p023.jpg', 23, 21),
  ('Кириченко Антон Трохимович', 'прадідусь Лосицького Никифора', 'Антон Трохимович народився у 1925 році в селі Завадівка Корсун- Шевченківського р-ну Черкаської області. 13.02.1944 був призваний до лав армії. Військове звання – червоноармієць, рядовий. Військова частина – 332 окрема розвідувальна рота 252-ої стрілецької дивізії. Загинув 24.08.1944 Був похований на теріторії Молдавської РСР, с. Німціни, біля річки Прут. Нагороди: «Орден Великої Вітчизняної війни 2 ступеня»', '/memory/p024.jpg', 24, 22),
  ('Журба Олексій Маркович', 'прадід Войтенка Михайла', 'Олексій Маркович народився 25 травня 1922 року в с. Пологи Теплицького району Вінницької області. У 1942 закінчив Київський військово- медичний інститут. Воював на Ленінградському фронті, був командиром санроти. У 1944 році був поранений. У подальшому своє життя присвятив флоту. Має нагороди: медалі «За оборону Сталінграда», «За оборону Москви», «Ордени Червоної Зірки», «Орден Вітчизняної війни 2 ступеня»', '/memory/p025.jpg', 25, 23),
  ('Журба Галина Іванівна', 'прабабуся Войтенко Михайла', 'Галина Іванівна народилася 1 травня 2023 року в місті Тобольск Тюменської обл. У 1944 р. закінчила Томський медичний інститут. У серпні1944 року була мобілізована на фронт, у складі 22 стрілецьій дивізії працювала лікарем у званні капітана медичної служби. Має нагороди: медалі «За відвагу», «За бойові заслуги», «За перемогу над Німеччиною», «Орден Вітчизняної війни 2 ступеня», «Орден Богдана Хмельницького 3 ступеня». Після війни працювала у Вентснільській громадській лікарні, потім у дитячій лікарні Печерського району м. Київ, згодом перейшла до поліклініку номер 1 Четвертого Головного управління при М3 УРСР. Похована у Києві 22 лютого 2009 р.', '/memory/p026.jpg', 26, 24),
  ('Красавцева Антоніна Петрівна', 'бабуся Красавцевої Крістіни', 'Антоніна Петрівна народилася 12.02.1922 р. у с. Челно-Вершини Куйбишевської обл. У 1943 р. добровільно вступила в ряди Радянської Армії. У вересні 1943 р. була направлена в московську школу снайперів, після закінчення якої проходила службу в діючий армії у складі жіночої роти снайперів 1 Українського фронту 13 загальновійськової армії 117 гвардійської стрілецької дивізії. У складі дивізійної роти снайперів брала участь у Львівсько-Сандомирської, Сандомирсько-Силезькій, Нижньо-силезської, Берлінській операціях. У1945 року була демобілізована. За доблесть та мужність, виявлені в ході бойових дій, нагороджена Орденом Великої Вітчизняної війни, медаллю «За відвагу» та іншими медалями.', '/memory/p027.jpg', 27, 25),
  ('Гончаренко Григорій Зіновійович', 'прадід Гончаренко Вікторії', 'Григорій Зіновійович народився у 1922 році в с. Ольшаниця Київської області. Був мобілізований до радянської армії влітку 1941 року. Йому було тоді лише 19 років. Брав участь в обороні Києва, де його частина потрапила в котел, але Григорію вдалося вийти з оточення і пішки пробратись в рідні місця на Київщині. У 1943 році, коли радянська армія почала визволяти Україну, Григорій Гончаренко повернувся на військову службу. Він служив у 3-й гвардійській танковій армії під керівництвом маршала Рибалка, був командиром кулеметного розрахунку. У складі танкової роти він брав участь в багатьох військових операціях: у 1944 році визволяв Львів , а в 1945 році - Варшаву. В травні 1945 року брав участь в битвах за Берлін та Прагу. Був двічі поранений, отримав контузію. Нагороджений Орденом Бойового Червоного Прапора, Орденом Червоної Зірки, бойовими медалями: «За відвагу», «За взяття Берліну», «За визволення Праги», «За визволення Варшави». Завершив військову службу Григорій Гончаренко в 1946 році у Відні командиром взводу. Після демобілізації повернувся додому, до матері, дружини та двох маленьких діточок. Да кінця життя працював в рідному селі Ольшаниця.', '/memory/p028.jpg', 28, 26),
  ('Шакалов (Шакала) Іван Костянтинович', 'прадідусь Гончаренко Ігора', 'Іван Костянтинович народився 17 вересня 1915 року в сім’ї коваля у селі Приазов’є Запорізької області. З 1937 року військову освіту здобував в Харківському Вищому Військовому Авіаційному Училищі Льотчиків (ХВВАУЛ), за спеціальністю пілот бомбардувальник. З небагатьох відомостей того періоду відомо, що він в 1939-1940 роках брав участь в радянсько-фінській війні, в травні 1940 року отримав медаль «За отвагу». Він виконував завдання, пілотуючи ТБ-3. Особливістю цієї моделі важкого бомбардувальника було те, що літак не міг здійснити посадку, якщо на борту залишався хоч один не використаний заряд. Під час одного з завдань його літак було збито. Він встиг катапультуватись і крізь ліси і болота Корелії, обморозивши кінцівки, з обпеченим обличчям добрався до своїх і потрапив в госпіталь. Після одужання був переведений до Москви і зарахований до Вищої школи розвідки при Генштабі СРСР (там же було змінено прізвище на Шакалов). По закінченні школи виконував обов’язки курівника розвідгрупи на лінії фронту, а пізніше як резидент Радянської розвідки в тилу ворога. На Батьківщину повернувся після звільнення Польщі від фашистів, закінчивши службу у березні 1947 року. Був представлений до нових нагород і одержав звання старшого лейтенанта. У 1945 році за наказом начальника Вищої Школи Розвідки Генерального Штабу отримав нагороду «За перемогу над Німеччиною у Великій Вітчизняній війні 1941-1945гг». І тільки у 1985 році отримав Орден Отечественной войны ІІ ступені. Всі довоєнні і воєнні документи залишились в московських архівах, тільки зараз деякі з них стали доступними з приміткою, що розсекречені у 2007 році («Розсекречено відповідно до наказу Міністра оборони РФ від 8 травня 2007 року N181 «Про розсекречення архівних документів Червоної Армії та ВійськовоМорського Флоту за період Великої Вітчизняної війни 1941-1945 років» (зі змінами на 30 травня 2009 р.)) Після війни закінчив Мелітопольський педінститут з правом викладання математики, фізики, астрономії, креслення, військової справи та німецької мови, та до пенсії викладав ці предмети в різних навчальних закладах. Помер на Київщині, м.Вишгород, 9.04.1992р.', null, 29, 27),
  ('Терещенко Олександр Корнійович', 'прадідусь Терещенко Софії', 'Терещенко Олександру на початку війни було 28 років. Він був одружений та мав донечку 2-х років, до війни жив у Києві на Куренівці та працював столяром. Вміння обробляти деревину далось взнаки і він став будувати мости для переправрадянських військ через річки. Часто доводилось робити це під ворожими обстрілами. Спочатку зводив понтонну переправу для відступу залишків наших військ через Дніпро, тому що міст було зруйновано ворожою авіацією. Пізніше він вже будував мости для наступу і звільнення України. Йому навіть вдалося потрапити у своє рідне село Синяк за Гостомелем у батьківську хату, де на той час вже переховувалась його дружина, а в 1945 вона зустрічала його ще й з малим сином. Потім Олександр Корнійович брав участь у звільнені Будапешту, звільняв Австрію та Чехословаччину у складі 2 Українського фронту. Закінчив війну у Празі.', '/memory/p030.jpg', 30, 28),
  ('Коханенко Василь', 'прадідусь Бащука Даніїла', 'Родинідуже мало відомо про нього, адже він помер в 1945 році, так і не дізнавшись про перемогу.', null, 31, 29),
  ('Олійник Кузьма Антонович', 'прадідусь Олійника Гліба', 'Олійник Кузьма Антонович(1892-1950) був капітаном річкового вантажного судна, а під час війни — капітаном бойового судна «Технік», яке входило до складу видатної Дніпровської Річкової Флотилії у складі Армії Радянського Союзу. Невдовзі перед війною Кузьма Антонович був призначений капітаном найбільшого в Україні пасажирського пароплава «Крупська». На ньому він зробив рейс із Гомелю до Києва на початку війни в червні 1941 року. Пароплав атакували німецькі літаки. Попри всі перешкоди супротивника, «Крупська» під командуванням Олійника К.А. дісталася Дніпром до Києва. Техніка й люди були збережені. На початку 1944 року Кузьма пройшов Дунай, різні річки і в боях дістався Німеччини. Запеклі бої тривалі на всій фашистській території. Олійник К.А. був нагороджений орденом Червоної зірки, медаллю «За перемогу над Німеччиною у Великій Вітчизняній війні 1941–1945 рр.»', '/memory/p032.jpg', 32, 30),
  ('Ситник Микита Андрійович', 'прадідусь Бічковського Кирила', 'На фото Микита Андрійович четвертий у другому ряду Микита Андрійович народився у с. Балабанівка Оратівського р-ну Вінницької області 15.09.1904. Навчався в Балабанівській церковнопарафіяльній школі. Призваний по мобілізації Полтавським РВК 13.06.1941 р. Війну пройшов рядовим з 18.06.41р. по 9 травня 1945 року в складі 74 інженерного авіабатальйону. Після демобілізації повернувся додому, відбудовував зруйноване господарство в рідному селі. Довго був комірником, обирався декілька разів народним засідателем. Нагороди: медалі «За оборону Сталінграда», «За перемогу над Німеччиною», «За звільнення Варшави», «За взяття Берліна» Помер 29 квітня 1991р', '/memory/p033.jpg', 33, 31),
  ('Момот Іван Федорович', 'прадідусь Кригіної Валерії', 'Іван Федорович народився 11 червня 1927року. Місце народження – с. Губівка Кіровоградської обл. З 1944 по 1951 служив у лавах воєнноморського флоту на тральщику, розміновував Чорне море. Закінчив службу в чині капітана 3 рангу. Після служби навчався в машинобудівному технікумі, працював на заводі «Мегометр» в Умані. Помер 11 лютого 2004, похований у Києві.', '/memory/p034.jpg', 34, 32),
  ('Власенко Іван Ілліч', 'прадідусь Дикого Кирила', 'Іван Ілліч народився 14.03.1914 р. у с. Багва Чернігівської обл. у сільській бідній родині. Після закінчення школи дуже хотів вчитись, тому для нього збирали всією сім’єю гроші на навчання. Навчався у Київському педагогічному інституті, працював вчителем математики в декількох сільських школах Київської області, потім - у Черкасах. Дуже любив дітей: міг терпляче і не дратуючись пояснювати матеріал, поки дитина не зрозуміє. Коли почалась війна, пішов на фронт. Воював недовго, бо отримав тяжке поранення. Після одужання служив у тилу військовим писарем, бо мав дуже гарний почерк. Під час війни померла його дружина від туберкульозу, довелося самому виховувати 4- річного хлопчика і 7-річну дівчинку. Працював вчителем у Київській школі. Багато займався з онуками, любив літературу, поезію. Помер у віці 92 років.', '/memory/p035.jpg', 35, 33),
  ('Карпенко Федір Кирилович', 'прадідусь Гоголіної Марії', 'Уродженець Полтавської області. Закінчив школусемирічку у червні 1941. Підлітком став членом кінного загону з боротьби з нацистськими парашутистами – шпигунами й диверсантами, потім був серед тих, хто допомагав переправляти евакуйованих з правового берега Дніпра на лівий. У серпні 1943 року сімнадцятирічний Федір добровольцем вступив до діючої армії, воював на Степовому, потім на Другому Українському фронтах. З боями пройшов від Дніпра до Праги, форсував Буг, Дністер, Прут, Реут, Серет, Тису. На все життя йому запам''яталися гарячі бої в районі Корсунь- Шевченківського, в Карпатах, участь в ЯсськоКишинівській операції, визволення Румунії, Угорщини, Чехословаччини. Довелося брати участь у розгромі японських мілітаристів. Дістав два поранення, кілька разів був контужений. Нагороди: Орден Червоної Зірки, Орден Слави III ступеня, медалі «За відвагу», «За бойові заслуги», «За перемогу над Німеччиною», «За перемогу над Японією»', '/memory/p036.jpg', 36, 34),
  ('Тупіков Григорій Ілліч', 'прадідусь Носко Анастасії', 'Григорій Ілліч народився в грудні 1918 року в с. Шумаково Орловської області. Був призваний на дійсну службу в ряди Червоної армії 27.09.1939 року. У серпні потрапив в оточення, а потім опинився в німецькому концентраційному таборі під Уманню, звідки його звільнила українка, яка назвала його своїм братом, врятувавши Григорія. З серпня 1943 воював у лавах регулярної армії в складі 283 стрілецької дивізії 3-го Білоруського фронту. Брав участь у Вітебській, Вітебсько-Оршанській, Мінській, Вільнюській, Каунаській, Мемельській, Гумбінненській наступальних операціях. Брав участь у боях за взяття Берліна. Нагороджений медалями «За відвагу», «За перемогу над Німеччиною», Орденом Вітчизняної війни II ступеня', '/memory/p037.jpg', 37, 35),
  ('Ворчак Петро Микитович', 'прадідусь Гончаренко Ігоря', 'Народився у 1909 році в м.Ічня Чернігівської області. Крім середньої освіти отримав вищу військову, закінчивши Московську військову академію (1935р). До початку окупації колишнього Радянського Союзу виконував військовий обов’язок в різних регіонах СРСР. Від початку окупації і до Дня Перемоги продовжував військову службу, за що був нагороджений двічі Орденом Червоної Зірки, двічі – Орденом Червоного прапору, Орденом Вітчизняної війни ІІ степени, медалями “За бойові заслуги”, «За перемогу над Німеччиною у Великій Вітчизняній війні 1941–1945 рр.», «За оборону Сталінграда» та іншими. Працюючи Заступником Начальника штабу з оперативної роботи завжди у найважчих умовах бою знаходився безпосередньо у підрозділах і вміло керував боями щодо винищення супротивника. Петро Ворчак для успішного проведення наступальних операцій завжди допомагав частинам артилерії з організації та проведення бою шляхом виїзду до бойових частин, хоча це загрожувало небезпекою для життя. Особисто керував боєм при взятті та обороні м.Любар, Тарнопіль, завдавши супротивнику великих втрат. Всі операції повністю забезпечував усім необхідним для успішного проведення їх, що сприяло успішному завершенню останніх з нанесенням противнику великих втрат у техніці та в живій силі. (https://pamyat-naroda.su/awards/32787639). Після закінчення Другої Світової Війни і до демобілізації в 1955р. в званні підполковника виконував в Угорщині обов’язки військового радника. Помер на Чернігівщині 15.12.1978р. .» (https://pamyat-naroda.su/awards/19761054)', '/memory/p038.jpg', 38, 36),
  ('Кропивка Петро Федорович', 'прапрадідусь Діденків Дмитра та Марії', 'Кропивка Петро Федорович народився у с. Наріжжя Полтавської обл. у 1902 р. Призваний в армію 13.11.1943 р. Кропивка П.Ф. був приписаний до 364 запасного стрілецького полку. Під час перебування у складі полку разом з іншими мобілізованими не був обмундирований, не отримав зброю, не отримував повноцінне харчування. Наприкінці грудня 1943 р. був відправлений під місто Рославль Смоленської обл. 1 лютого 1944 р. за бойовим розпорядженням №1 штабу 53 стрілецького корпусу 48А брав участь у бойовій розвідці переднього краю оборони супротивника в районі с. Кобильщина в складі 400 бійців. Кропивка П.Ф. воював лише п‘ять годин. Це був перший і останній бій: розвідка боєм – наступ по полю шириною 800 м без зброї, у домашньому одязі проти шести батальйонів. Бойова задача не була виконана «благодаря неумелому руководству командного состава батальона», було вбито та поранено 123 бійці. Більшість вбитих, в тому числі, Петро Федорович Кропивка, залишились на полі бою і були поховані лише через кілька місяців.', '/memory/p039.jpg', 39, 37),
  ('Креневич Іван Максимович', 'прадід Креневич Ярослави', 'Іван Максимович народився 14.05.1923 р. в селі Нобель Зарічненського району Рівненської області. До лав армії був мобілізований в травні 1945 р. Служив розвідником у 756-му стрілецькому полку 150-ї стрілецької дивізії 3-ї ударної армії 1го Білоруського фронту. Відомий епізод, коли він зненацька наскочив на групу німецьких солдатів, але не розгубився – сміливо увірвався у ворожу траншею й знищив 13 гітлерівців. У складі взводу розвідки 756-го стрілецького полку забезпечував підняття Прапора Перемоги над рейхстагом. Після повернення з фронту жив і працював у рідному селі. Помер 12.05.2006 р. (Біля прапора Перемоги. Справа – Єгоров Михайло, зліва – невідомий офіцер, посередині в глибині знімка – Креневич Іван Максимович) За взяття Берліна отримав орден Вітчизняної війни ІІ ступеня, а також нагороджений декількома бойовими медалями.', '/memory/p040.jpg', 40, 38),
  ('Креневич Іван Оксентійович', 'прапрадід Креневич Ярослави', 'Іван Оксентійович народився 13.11.1909 р. в селі Нобель Зарічненського району Рівненської області. Був мобілізований у травні 1944 р. Воював рядовим у 756-му стрілецькому полку 150-ї стрілецької дивізії 3-ї ударної армії 1-го Білоруського фронту, служив стрільцем (кулеметником, автоматником). В боях за Прибалтику у вересні 1944 р. був тяжко поранений і після піврічного лікування демобілізований по інвалідності в березні 1945. Вижив випадково: під час обіду вийшов з польової кухні, а через якусь мить туди влучив потужний фугасний заряд, утворивши на тому місці величезну вирву. Загинули всі, хто там був; його ж контузило, осколками перебило ноги та посікло тіло. Після війни жив і працював у рідному селі. Про війну не любив говорити і на урочисті зібрання ветеранів майже не ходив, хоч воював гідно, про що свідчать його нагороди: орден Вітчизняної війни ІІ ступеня та декілька бойових медалей. Помер 14.02.1998 р.', '/memory/p041.jpg', 41, 39),
  ('Тетерчев Дмитро Тимофійович', 'прадідусь Мілюкова Романа', 'Дмитро Тимофійович народився 30 жовтня 1911 року у селі Кащєєво Бельовського району Тульської області. До війни був співробітником карного розшуку. За рішенням Череповецького райкому партії 2.09.1941 року в районі було створено партизанський загін «Передовий». Командиром загону став мій прадід. У лісі були вириті землянки, в яких зберігалося продовольство, боєприпаси, теплі речі, інструменти для розбирання залізничних шляхів. Загін діяв на найважливішій для противника залізничній магістралі Лихвин – Козельськ - Сухиничі. Партизани виконували цілий ряд завдань: у тилу ворога пускали поїзди під укіс, займалися контрпропагандою й інформуванням населення про становище на фронтах, зривали підвезення боєприпасів, озброєння, продовольства і живої сили ворога. Одночасно з інформуванням, листівки партизан закликали до здійснення диверсій і знищення ворожих солдатів і офіцерів. 26-го грудня Червона Армія зайняла місто Лихвин і партизанський загін з''єднався з частинами регулярної армії. Дмитро Тимофійович нагороджений Орденом Леніна та Орденом Вітчизняної війни II ступеня', '/memory/p042.jpg', 42, 40),
  ('Мостовий Іван Леонтійович', 'прадідусь Токаревої Жанни', 'Іван Леонтійович народився 26.05.1916 у с. Залуччя Смотрицького р-ну, Кам’янець-Подільської обл. До війни був військовим. На війну призвали у липні 1941 р., служив в авіації у чині майора. Брав участь в боях за Сталінград, Прагу, Будапешт, звільняв Україну. Був поранений. Після війни працював у метеорологічній службі. Був нагороджений Орденом Червоної Зірки та медалями.', '/memory/p043.jpg', 43, 41),
  ('Двірний Іван Дмитрович', 'прадід а Двірного Максима', 'Двірний І.Д. народився 2.09.1906 р. На фронті з 1941р. Згодом потрапив у полон та опинився в таборі для військовополонених біля Черкас. Через декілька місяців полону німці відпустили його і всіх військовополонених, які до війни мешкали у Черкасах. З того часу до 1943р, поки Радянські війська не звільнили місто та область, переховувався у лісах Черкащини. У 1943р приєднався до лав Українського фронту. Перемогу зустрів у Німеччині неушкодженим. Загинув 22.08 1945р в Німеччині, там і похований.', '/memory/p044.jpg', 44, 42),
  ('Федоренко Степан Антонович', 'прадід Двірного Максима', 'Степан Антонович народився у 1911 році До війни працював шкільним вчителем в селі Середи на Житомирщині, був викладачем фізики, математики і музики. Воював на фронті з 1941р. У 1942-1943р під Сталінградом був тяжко поранений (кульове поранення легенів). З того часу перебував у військовому госпіталі у Казахстані. Після закінчення війни повернувся до мирного життя і продовжив викладати. Помер у 1957 році. Фотографії, на жаль, не збереглися.', null, 45, 43),
  ('Менжега Микола Олексійович', 'прадід Геруса Назара', 'Менжега М. О. народився 6 березня 1925року в с. Красилівка Броварського р-ну Київської обл.. Мобілізований до лав Радянської армії у 1943році. Служив звʼязківцем-телефоністом 2-го дивізіону 365-го артилерійського полку 163-ї стрілецької дивізії 38-ї армії; Брав участь у боях за звільнення України, зокрема м.Києва на Лютізькому плацдармі, Молдови, Румунії, Чехословаччини, Австрії. День Перемоги зустрів у австрійському місці Грац. За зразкове виконання бойових завдань під час звільнення багатьох міст України і Європи, зокрема за форсування ріки Дністер, форсування р. Дніпро у вересні 1943р., утримання плацдарму на західному березі р. Дунай, має Подяки Верховного Головнокомандуючого, командувача Воронезьким фронтом генерала армії Ватутіна, командувача 3-м Українським фронтом Маршала Толобухіна. Нагороджений під час бойових дій двома медалями «За відвагу», «Медаллю за взяття Будапешта».', '/memory/p046.jpg', 46, 44),
  ('Москаленко Микола Федотович', 'прадід Дмитрука Олега', 'Микола Федотович народився в 1918 році на Полтавщині. Пішов на війну в 23 роки. Брав участь у форсуванні Дніпра. Старший лейтенант, командир батареї мінометного полку “Катюша”. Пройшов всю війну. Мав поранення. Був нагороджений орденами Вітчизняної війни I та II ступенів, Червоної Зірки та шістьма медалями. Після війни працював головним редактором районної газети в м. Кролевець, Сумської області. Загинув у 1971 р., рятуючи потопаючу дівчинку.', '/memory/p047.jpg', 47, 45),
  ('Павловський Микола Остапович', 'прадід Дмитрука Олега', 'Микола Остапович народився в 1911 р. на Вінниччині. Освіту отримав у Бердичівській педагогічній школі. Напередодні війни був призваний до армії. Під час війни в 1941 році військова частина, в якій він служив радіозв’язківцем, виявилася під Києвом в оточенні, з якого вийти не вдалося. Окупованими українськими землями повернувся в село, де жив у той час, продовжив вчителювати, а через деякий час був знову мобілізований на фронт. В кінці війни, у 1944 році був тяжко поранений у Чеських Карпатах, довго лікувався у госпіталі на Уралі. Нагороджений орденом Червоної Зірки і декількома медалями. Після війни працював за фахом, учителем фізики і математики на Житомирщині. Досі живі багато його колишніх учнів, які з теплотою і вдячністю згадують свого вчителя. Помер у 1995 році.', '/memory/p048.jpg', 48, 46),
  ('Іголкін Володимир Назарович', 'прадід Іголкіна Єгора', 'Володимир Назарович народився в селі Петрівка Луганської області. Війну зустрів у званні капітана, командував 45-м прожекторним полком у складі 1-го корпусу ППО Москви Особливої Московської Армії ППО, потім - 3-й зенітнопрожекторної дивізією цієї ж армії в складі Центрального фронту ППО. Виконував бойові завдання з протиповітряної оборони міст Москви і Горький. Після війни вже у званні полковника командував 1-ої зенітно-прожекторної бригадою, потім дивізією ППО Бакинського району ППО, був військовим радником в Китаї, начальником курсу Артилерійській радіотехнічної Академії СА. Нагороджений орденами Леніна, Червоного Прапора, Червоної Зірки, медалями.', '/memory/p049.jpg', 49, 47),
  ('Кирилюк Іван Федосійович', 'дідусь Кирилюка Георгія', 'Кирилюк І.Ф. народився 8 червня 1923-го року в село Старі Бабани Уманського району Київської області. Після закінчення військового училища (1941-1942р.р.), направлений на фронт командиром взводу кулеметників. Був поранений у 1942р. та на початку 45-го року. Воював на Українському фронті. Брав участь у боях за Австрію, перемогу зустрів у Чехословаччині в Празі. Нагороджений багатьма медалями та орденами ￼', '/memory/p050.jpg', 50, 48),
  ('Лосачев Олександр Іванович', 'прадід Кирилюка Георгія', 'Відомо, що гвардії майор Лосачев О.І. був командиром окремого танкового батальйону 1-го Далекосхідного фронту.', '/memory/p051.jpg', 51, 49),
  ('Мітін Микола Олександрович', 'прадід Корольова Нікіти', 'Мітін М.О. під час війни закінчив танкове училище. У бойових діях брав участь під час Маньчжурської стратегічної наступальної операції 1945 року, яка проводилась з метою розгрому японської Квантунської армії в якості військового кореспондента. Під час боїв був поранений. Після закінчення Другої світової війни навчався у Військово-політичної академії ім. В.І.Леніна. Служив на Тоцькому полігоні в Оренбурзькій обл, Уссурійську Приморського краю, Середній Азії, Сімферополі, Польщі. Військову службу завершив в штабі Київського військового округу. До виходу на пенсію попрацював і на цивільній посаді – директором Куренівського парку м. Києва. Нагороджений орденами «Червоного Прапора» та «Вітчизняної Війни 1 ступеня», медалями «За бойові заслуги», «За перемогу над Німеччиною», «За перемогу над Японією»', '/memory/p052.jpg', 52, 50),
  ('Савченко Микола Ілліч', 'прадідусь Олександра та Ярослава Лішенків', 'Савченко Микола Ілліч народися 21.11.1912 в м. Козелець Чернігівської обл. Був слухачем 2го курсу Військово-повітряної академії в м. Москва, коли 22 червня 1941 року фашистська Німеччина напала на Радянський Союз. У складі сформованої в академії бомбардувальної ескадрильї Савченко Микола Ілліч вилетів на аеродром під Києвом. Бомбардувальники здійснювали польоти для бомбування німців під Коростенем, Тернополем, Харковом. З другої половини війни Савченко М.І навчав пілотів бомбардувальної авіації. Після закінчення війни займався розвитком реактивної авіації в м. Ахтубінськ Астраханської обл. З 1960 по 1989 рік працював на виробництві в місті Слов’янськ Донецької обл. Рік смерті – 1992 Має нагороди: медалі «За перемогу над Німеччиною», «За бойові заслуги», ордени Червоної Зірки та Червоного Прапора', '/memory/p053.jpg', 53, 51),
  ('Богатюк Семен Михайлович', 'прадід Липяцького Олександра', 'Богатюк С.М. народився у 1924 році в с. Єгорівка, Старо-Керменчикського району Донецької (Сталінської) області. Воював у лавах збройних сил з серпня 1943 року в складі 327 гірсько-стрілкового полку, який брав участь у звільненні Кубані, Криму, Севастополя. Був тяжко поранений, лікувався в Кисловодську. З 8 вересня 1944 року у складі 327 полку 128 окремої Гвардійської ТуркестаноЗакарпатської дивізії 4 Українського Фронту брав участь у Східно-Карпатській наступальній операції, у боях за звільнення Чехословаччини. 21 вересня 1944 р. звільнили перший населений пункт на території Чехословаччини (сучасної Словаччини) – с. Каленов. Загинув 25 вересня 1944 року при звільненні населеного пункту Зубраче. Нагороджений Орденом Червоної зірки, який після війни був вручений родині. Моя бабуся Валентина ніколи не бачила свого тата і про її народження він дізнався з листа родини на фронт.', '/memory/p054.jpg', 54, 52),
  ('Ананьїв Іван Олексійович', 'прадід Молоканова Костянтина', 'Ананьїв І.О. народився 20.01.1905 На фронті з 1941 по 1945 рр. Воював на Західному та 3-ому Білоруському фронтах у званні капітана арт-тех служби. Був помічником начальника артпостачання 159 Стрілецької Вітебської Червонопрапорної ордена Суворова 2 ступеня дивізії. За час бойових дій дивізії під час форсуванні річки Шешупе в районі Байорайце та в районі Петерлаукен, Добледжен, Вільпішен, Йукнішен в важких умовах під сильним арт. вогнем та неодноразових контратаках противника зумів організувати переправу спецзасобів на бойові позиції гарматних і мінометних батарей. Нагороджений орденом Червоної Зірки та медалями «За перемогу над Німеччиною» та «За перемогу над Японією».', '/memory/p055.jpg', 55, 53),
  ('Молоканов Геннадій Іванович', 'двоюрідний дід Молоканова Костянтина', 'Геннадій Іванович народився 27.11.1926р. В травні 1944р. був призваний в Радянську армію. Брав участь у війні з Японією, за що в 1945 році був нагороджений орденом Червоної Зірки У 1949р. написав листа Й. В. Сталіну з критикою порядків в армії, за що був засудженим на 10 років за статтею 53. У 1955р. його реабілітували (довідка від 08.02.1955р.). Закінчив Філологічний факультет Педагогічного інституту, потім Новочеркаський Політехнічний інститут. Кандидат технічних наук, доктор філософських наук, президент Кубанської Народної Академії, заслужений діяч науки. Помер у 2005 році.', '/memory/p056.jpg', 56, 54),
  ('Молоканов Іван Павлович', 'прадід Молоканова Костянтина', 'Іван Павлович народився 29.06.1900р. З 1922року працював вчителем в різних закладах народної освіти. У 1936 році закінчив Педагогічний інститут за спеціальністю «математика», працював вчителем, завучем. У вересні 1941р. Молоканова Івана Павловича призвали до лав РККА, де він був радистом. Під час Харківської операції (12 травня 23 травня1942р) був тяжко поранений та захоплений в полон, де загинув від ран. Про це розповів однополчанин прадіда. (Повідомлення про загибель додається).', '/memory/p057.jpg', 57, 55),
  ('Бердник Мойсей Трохимович', 'прадід Натальченка Мирослава', 'Бердник М.Т. народився у 1922 році в Кіровоградській області (нині Черкаська область) у селі Завадівка. Із характеристики військового командування «У червні 1944 Бердник М.Т. брав участь у наступальних боях полку на р. Дністер. Його взвод відбив 3 атаки, сам боєць знищив понад 10 супротивників. У бою біля с. Греблі його взвод вибив нацистів з висоти. Коли супротивник пішов у контратаку, тов. Бердник вміло зупинив наступ. У цьому бою був поранений і евакуйований на лікування.» Нагороджений орденом Червоної Зірки та медаллю «За перемогу над Німеччиною»', '/memory/p058.jpg', 58, 56),
  ('Шугурова Анна Андріївна', 'прабабуся Натальченка Мирослава', 'Анна Андріївна народилась у Житомирській області у 1906 році. Воювала з 1941 по 1945 рік. Була розвідницею. Досконало володіла польською мовою. Була заслана до польської армії, в якій воювала до визволення Польщі від нацистів. Потім повернулась на службу до лав Червоної армії. Отримала орден Вітчизняної війни 2 ступеня.', '/memory/p059.jpg', 59, 57),
  ('Шугуров Петро Іванович', 'прадід Натальченка Мирослава', 'Петро Іванович народився в Куйбишевській області у селі Кузьмино у 1906 році. Воював з 1941 по 1945 рік. Брав участь у Сталінградській битві. Був капітаном державної безпеки. Здобув ряд корисних матеріалів для Військової ради фронту. Отримав ордени Червоної Зірки та Вітчизняної війни 1 та 2 ступенів.', '/memory/p060.jpg', 60, 58),
  ('Мішенін Олексій Степанович', 'прадідусь Юстина Паламарчука', 'Мішенін О.С. народився у 1917 році. До війни був вчителем математики у селі Теребрине Білгородської області. Під час війни був мінометником. Військове звання –сержант. Загинув у 1944 році, похований у с.Конела Черкаської області.', '/memory/p061.jpg', 61, 59),
  ('Паламарчук Леонід Олександрович', 'прадідусь Юстіна Паламарчука', 'Рік народження Паламарчука Л.О. – 1914. До війни був вчителем історії і німецької мови, директором школи у м.Чортків Тернопільської області. Під час війни командував артилерійським дивізіоном, брав участь у розвідницьких операціях. Нагороджений Орденом Великої вітчизняної війни 2 ступеня, Орденом Червоної зірки, медаллю "За відвагу". Похований у 1990 році.', '/memory/p062.jpg', 62, 60),
  ('Носаєв Василь Іванович', 'прадід Половнева Артема', 'До лав Радянської Армії призвали у 1939 році (Ленінградський округ). Там у 1941 його застав початок війни. Був старшиною роти. Брав участь у бойових діях під Воронежем, у першому звільненні Харкова. Під Сталінградом опинився в оточенні, де двічі під час боїв був поранений, лікувався у шпиталі. За те, що потрапив в оточення, засуджений до штрафбату, де і продовжив захищати Батьківщину. Разом з чорноморськими моряками штурмував Сапун-гору в Криму. У другій хвилі штурмуючих зійшов на Сапун-гору, за що і був удостоєний нагороди Орденом Червоної Зірки. Але нагородження не було затверджено. Пізніше потрапив у підрозділ з охорони дороги Тегеран-Москва. День Перемоги зустрів у Тегерані. Отримав дві бойові медалі «За відвагу». У 1949 році демобілізувався. Повернувся у рідне село та став сільським агрономом. У 1975 році , нарешті, отримав свою нагороду.', '/memory/p063.jpg', 63, 61),
  ('Розов Борис Якович', 'прадід Гусєєвих Марії та Єгора', 'Борис Якович під час війни був танкістом. Воював під Ржевом. Пройшов з боями через Білорусь та Литву. Під час одного з боїв витягував підбитий танк і врятував поранених танкістів. Нагороджений орденом Червоної Зірки', '/memory/p064.jpg', 64, 62),
  ('Мороз Іван Петрович', 'прадід Красновських Поліни та Андрія', 'Іван Петрович війну зустрів курсантом. Пройшов бойовий шлях з 1941 по 1945 у складі окремої 48-ї зенітної артилерійської бригади ППО від молодшого командира до начальника ППО. Воював на Ленінградському фронті. Був поранений. Має нагороди, у тому числі медаль «За оборону Ленінграда». Повернувся додому живим.', '/memory/p065.jpg', 65, 63),
  ('Пузін Борис Миколайович', 'прадід Пустовойта Микити', 'Борис Миколайович воював з 1941 по жовтень 1945 року. Брав участь у визволенні Донеччини, Праги, Болгарії. Був нагороджений Орденом Червоної Зірки в 1943, Орденом Вітчизняної Війни II ступеня в 1985 році, медаллю «За визволення Праги» і медаллю «За перемогу над Німеччиною у ВВВ 1941-1945 рр.»', '/memory/p066.jpg', 66, 64),
  ('Бояринцев Олександр Овсійович', 'прадід Шумара Петра', 'Олександр Овсійович народився 13.03.1913р. у Харкові в сім''ї робітника. У 1928 році закінчив Козелецьку семирічну школу. До війни закінчив сільськогосподарський технікум, працював у колгоспі агрономом. У 1939 році був призваний до армії. Воював з вересня 1939р. по 10.08.1946р. у складі Північно-Західного, ІІ Українського, ІІІ Українського, Далекосхідного фронтів. Має нагороди: Медаль «За перемогу над Німеччиною», Орден Вітчизняної війни II ступеня, Орден Червоної Зірки, медаль «За відвагу». Помер 7.10.1990р.', '/memory/p067.jpg', 67, 65),
  ('Семичев Сергій Олексійович', 'прадід Марії Нижник', 'Семічев С.О. народився 8 жовтня 1925р. 23 січня 1943 року призваний до Радянської Армії. З листопада по серпень 1943 року – рядовий 95-го запасного стрілецького полку і 1го відділення артилерійського протитанкового дивізіону, 14 відділення запасної стрілецької бригади МВО. З серпня 1943 по грудень 1944 року - курсант Арзамаського стрілецько-мінометного училища; з грудня 1944 року по квітень 1945 року –служив у 53 офіцерськом полку резерву. Перемогу 1945 прадід зустрів у місті Будапешт. Сергій Олексійович все життя присвятив службі в армії (служив до 70 років). Мав ордена та нагороди. У 1976 року отримав звання полковника.', '/memory/p068.jpg', 68, 66),
  ('Семичев Олексій Абрамович', 'прапрадід, Семичев Анатолій Олексійович- двоюродний', 'прадід Марії Нижник Семичев О.А. та Семичев А.О. загинули на війні та вважилися зниклими без вісті. У 1980 роках знайдені та ідентифіковані їх тіла. Вони поховані у братських могиліах загиблих у боях 1941-1943 роках в Харківської та Московській областях.', '/memory/p069.jpg', 69, 67),
  ('Тютюнников Віктор Ілліч', 'прадід Вероніки та Маргарити Андріанових', 'Тютюнников В.І. народився у 1926 р. в родині селянина. Після закінчення 9-го класу вступив до Іркутського військового авіаційного технічного училища, після закінчення якого набув спеціальність авіаційного механіка. У 1943 р. був призваний до лав армії і відправлений на фронт, служив на Сахаліні. Брав участь у бойових діях у радянсько-японській війні. Отримав багато нагород, у тому числі медаль “За бойові заслуги” й Орден Вітчизняної війни 1941-1945 р. Після закінчення Другої світової війни продовжував нести службу в рядах радянських військ. У 1974 . Тютюнников В.І. був демобілізований і вийшов на пенсію у званні підполковника. Помер Тютюнников Віктор Ілліч в 1995 р.', '/memory/p070.jpg', 70, 68),
  ('Алєксєєв Гліб Іванович', 'прадід Салана Михайла', 'Гліб Іванович народився у 1921 р. Учасник бойових дій з 1942 по 1945 рік. На фронт пішов добровольцем. Воював на Курській дузі, брав участь у боях за звільнення Липецької області, Києва. Далі – Румунія, Чехословаччина, Угорщина, Австрія. Бойові нагороди: Орден Червоної Зірки, медалі «За перемогу над Німеччиною», «За бойові заслуги», «За взяття Будапешта», «За взяття Відня».', '/memory/p071.jpg', 71, 69),
  ('Алєксєєва (Шлапак) Раїса Петрівна', 'прабабуся Салана Михайла', 'Раїса Петрівна народилася у 1920 році. Учасниця бойових дій з 22.06.41 по 1945 рік. Пройшла бойовий шлях від Одеси до Кубані, а потім у зворотному напрямку через Україну до Румунії. Служила медсестрою у військовому шпиталі. Нагороджена медаллю «За перемогу над Німеччиною».', '/memory/p072.jpg', 72, 70),
  ('Семіч Марія Родіонівна', 'прабабуся Салана Михайла', 'Марія Родіонівна народилася у 1919 році. Учасниця бойових дій з 1943 по 1945 рік. Служила радисткою на військовій радіостанції. Першою з мешканців м. Козятина отримала звістку про капітуляцію Німеччини і перемогу СРСР у війні. Нагороджена медаллю «За доблесну та самовіддану працю в період Великої Вітчизняної війни» та значком «Учасник бойових дій».', '/memory/p073.jpg', 73, 71),
  ('Морозов Іван Опанасович', 'прадідусь Мещана Івана', 'Роки життя: 21.08.1922-23.09.1997. Воював з вересня 1941 р. по травень 1945 р. Учасник битви за Сталінград і Курськ, звільняв Прагу та штурмував Берлін. Пройшов шлях від гвардії рядового до гвардії підполковника, був начальником розвідки дивізії. Брав участь в Параді Перемоги в Москві . Нагороджений Орденом Червоного Прапора, двома Орденами Червоної Зірки. Кавалер трьох Орденів Великої Вітчизняної війни. Має медалі «За бойові заслуги», «За взяття Берліна», «За визволення Праги», «За оборону Сталінграда», медаль польського уряду та медаль учасника Параду Перемоги.', '/memory/p074.jpg', 74, 72),
  ('Корнійчук Петро Тихонович', 'прадідусь Корнійчуків Назара та Соломії', 'Петро Тихонович народився у 1924 році. Місце народження: Кам''янець-Подільська обл., Старо-Костянтинівський р-н, с. Б. Чернятин. Воював з 1944 по 1945 р. Був стрільцем роти автоматників. В боях неодноразово виявив доблесть та мужність. Так 29.11.1944 у складі роти брав участь в танковому десанті, у результаті якого був взятий населений пункт Лесне. За цей бій Петро Тихонович отримав медаль «За відвагу». При взятті Гергерсдорфу 28.04.1945 був одним з перших, хто увірвався в населений пункт. За цей бій був нагороджений Орденом Слави ІІІ ступеня.', '/memory/p075.jpg', 75, 73),
  ('Ткаля Тимофій Омелянович', 'прадід Євгенії Данилової', 'Ткаля Т.О. народився у 1914 р. у Запорожській обл. у с. Поповка. До лав радянської армії призваний у 1941 році у званні старшого лейтенанта. Під час війни був кулеметником, командував ротою автоматників, мінометним підрозділом. Дійшов до Берліна. Мав неабияку військову кмітливість, вміло і сміливо міняв вогневі позиції. Має нагороди: орден Червоної Зірки, орден Вітчизняної війни I та II ступенів, орден Красного Знамені', '/memory/p076.jpg', 76, 74),
  ('Кирдан Миколай Іванович', 'прапрадід Андрія Чорноівана', 'Микола Іванович народився у м. Кременець в 1901 р.. Пройшов весь шлях війни від України до Німеччини. У 1943 році нагороджений орденом Червоної Зірки, у 1944 орденом Богдана Хмельницького другого ступеню, у 1945 році - орденом Червоного Знамені та орденом Великої Вітчизняної Війни 1 ступеня. Мав численні бойові поранення, був відважним та шанованим бійцем.', '/memory/p077.jpg', 77, 75),
  ('Головань Афанасій Кирилович', 'прадід Володимира Голованя', 'Воював з 1941 по 1945 рік у бронетанкових військах. Завершив війну у Берліні. Нагороджений орденом Червоної Зірки, медалями за взяття Кенігсберга та Перемогу над Німеччиною', '/memory/p078.jpg', 78, 76),
  ('Ціленко Іван Миколайович', 'прадід Микити Панфілова', 'У грудні 1941 пішов добровольцем на фронт. Пройшов всю війну. Воював у складі 385 саперного полку 112 стрілецької Ризько- Коростенської червонопрапорної ордена Суворова дивізії. При форсуванні Дніпра був тяжко поранений, близько сотні осколків залишилось в тілі, які носив у собі до кінця життя. Нагороджений орденом «Вітчизняної війни» та багатьма медалями', '/memory/p079.jpg', 79, 77),
  ('Литвинов Яків Якович', 'прапрадід Гліба Конберга', 'На початку війни був направлений на фронт зам.нач.особливого відділу 136 Окремої Стрілкової Бригади, в якої воював до 1943 року. Після важкої контузії та поранення лікувався у госпіталі, а з лютого 1945 року до кінця війни воював у Німеччині в складі 2-го Українського фронту. Нагороджений медаллю За перемогу над Німеччиною, орденом Вітчизняної Війни 2 ступеня.', '/memory/p080.jpg', 80, 78),
  ('Шкабара Сергій Матвійович', 'прапрадід Богдана та Володимира Кучерів', 'Старший сержант Шкаруба С. М. під час війни був санінструктором. Служив в 53 гвардійській танковій бригаді. Загинув 20.02.1945 в с. Хохкірх, р-н м.Гарліц, Німеччина.', '/memory/p081.jpg', 81, 79),
  ('Трикуш Павло Якович', 'прадід Христини та Софії Троцько', 'Наприкінці 1943 року був призваний до лав червоної армії і боровся за Батьківщину в 526 стрілецькому полку 89 стрілецької Таманської Дивізії . Був розвідником. За хоробрість, стійкість, мужність, за зразкове виконання бойових завдань на фронті боротьби з німецькими окупантами нагороджений Орденом Вітчизняної війни I ступеня, Орденом Червоної Зірки; медалями «За відвагу , «За взяття Берліна», «За перемогу над Німеччиною у Великій вітчизняній війні1941-1945 рр. .» та ін. Червоноармієць Трикуш Павло Якович брав участь у героїчному штурмі і взятті столиці фашистської Німеччини Берліна. При форсуванні річки Одер він був важко поранений у праву частину грудної порожнини. І тільки лише наприкінці листопада 1945 після тривалого лікування повернувся додому.', '/memory/p082.jpg', 82, 80),
  ('Сергіїв Олександр Іванович', 'прадід Олександра та Валерії Деменкових', 'У званні інженер-капітана служив в лавах Червоної Армії з 1939р. Воював у складі 2-го Українського фронту. Закінчив війну в Угорщині. Нагороди: - «За бойові заслуги», - «За оборону Сталінграда», - «За взяття Будапешта», - Орден Вітчизняної війни 2го ступеня, - Орден Червоної Зірки.', '/memory/p083.jpg', 83, 81),
  ('Горобець Іван Мойсейович', 'прадід Олександра та Валерії Деменкових', 'В лавах Червоної Армії – з червня 1941р. Був сержантом, старшим інструктором 29-го окремого батальйону. Воював на 3-ому Українському фронті. Закінчив війну в Берліні. Нагороджений медалями «За бойові заслуги», «За оборону Сталінграда», «За взяття Берліна»', '/memory/p084.jpg', 84, 82),
  ('Бухаров Іван Васильович', 'прадід Владислава Прищепи З початку війни був призваний', 'до лав армії. В 1943 році у боях на Курській дузі був важко поранений розривною кулею. Після війни працював у колгоспі.', '/memory/p085.jpg', 85, 83),
  ('Ватагін Кузьма Якович', 'прадід Владислава Прищепи', '16 липня 1941 року пішов добровольцем на фронт. Воював у мінометній батареї. У 1942 році загинув при обороні Севастополю.', '/memory/p086.jpg', 86, 84),
  ('Красніков Іван Федорович', 'прадід Дмитра Скоробагатька', 'Лейтенант. Брав участь у захисті Сталінграду та взятті Берліну. Має безліч нагород, серед яких Орден червоної зірки, медаль за взяття Берліну та інші.', '/memory/p087.jpg', 87, 85),
  ('Розов Борис Яковлевич', 'прадід Егора Гусєєва', 'Був танкістом. Пройшов з боями через Ржево, Білорусь та Литву. Під час одного з боів витягував підбитий танк та допомагав пораненим. Отримав орден Червоної Зірки.', '/memory/p088.jpg', 88, 86),
  ('Бойко Іван Акимович', 'прадід Нікіти Шевцова', 'Пройшов всю війну. Двічі форсував Дніпро (Букринський плацдарм). Розвідник, двічі був поранений. Орденоносець, має медаль За відвагу. Полковник, почесний громадянин Києва. Керував ветеранської організацією Шевченківського району.', '/memory/p089.jpg', 89, 87),
  ('Бармак Володимир Самійлович', 'прадід Михайла Клименко', 'Після закінчення 8 класу середньої школи вступив до Харківського військового училища, після випуску з якого у 1944 році служив у складі військ Другого українського фронту, брав участь у звільненні Угорщини від німецькофашистських загарбників. 9 Травня 1945 року зустрів у Будапешті. У подальшому продовжив військову службу і був направлений у м. Бєльці (Молдавія). Після демобілізації заочно закінчив історичний факультет Одеського університету.', '/memory/p090.jpg', 90, 88),
  ('Ковальов Олександр Федотович', 'прадід Володимира Вилущака', 'Коли почалася війна, працював на Шосткінському військовому заводі, де виготовляв боєприпаси для армії. З вересня 1941, після евакуації заводу, воював зв’язківцем у піхоті. В 1943 році був тяжко поранений у руку, не зважаючи на загрозу життю, відмовився від ампутації, після тривалого лікування був комісований і повернувся в рідне село. Працював головою колгоспу.', '/memory/p091.jpg', 91, 89),
  ('Тонкошкур Василь Антонович', 'прадід Ксенії Тонкошкур', 'Після закінчення 9-го класу пішов на фронт, Пройшов багато доріг Великої Вітчизняної Війни. З 1945 року – ревізор, перший секретар комсомолу Богуславського району Київської області. З 1954 року служив на флоті протягом чотирьох років. Має нагороди: ордена Леніна, бойової слави III ступеня, Б. Хмельницького, Вітчизняної війни II ступеня.', '/memory/p092.jpg', 92, 90),
  ('Удовик Іван Венедиктович', 'прадід Олесі Славської', 'Старший лейтенант інженерних військ. Загинув у Польщі у лютому 1945 року', '/memory/p093.jpg', 93, 91),
  ('Соболев Володимир Ілліч', 'прадід Володимира та Ігоря Сачків', 'У 1943 році у 18 років пішов добровольцем на фронт. Війну закінчив у чині сержанта. Помер 7 травня 1989 року.', '/memory/p094.jpg', 94, 92),
  ('Венедиктов Михайло Віталійович', 'прадід Володимира та Ігоря Сачків', 'У перші дні війни проходив підготовку в школі молодшого командного складу в Кушці. По закінченню школи у званні молодшого лейтенанта був спрямований командувати взводом мінометників 4-го Українського фронту. Брав участь у боях під Вірменськом, Джанкоєм. У 1943 році був поранений, а у 1944 році комісований в званні лейтенанта. Нагороджений медалями За звільнення Кавказу, За перемогу над Німеччиною, За відвагу.', '/memory/p095.jpg', 95, 93),
  ('Печерський Леонід Маркович', 'прадід Гліба Мальченко', 'Воював з 1939р. на фронтах Другої Світової війни. Закінчив війну у Варшаві. Був танкістом, горів у танку.', '/memory/p096.jpg', 96, 94),
  ('Жмайло Лука Андрійович', 'прадід Олександра Жмайло', 'Воював з 1941 по 1945. При визволенні Києва був контужений та отримав важке поранення. Після лікування повернувся до лав Армії та дійшов до Східної Пруссії. З п’яти братів він один повернувся живий з війни. Нагороджений медалями За відвагу (1943), За бойові заслуги (1945).', '/memory/p097.jpg', 97, 95),
  ('Павлов Олексій Кузьмич', 'прапрадід Дмитра Колісника', 'Воював з перших днів війни. У 1945 – став заступником начальника оперативного управління 2го Білоруського фронту, генералмайор. СТАЛЬ і НІЖНІСТЬ - цей нарис дуже символічний. Все життя він любив землю, міг стати гарним природознавцем, але прийшла війна і він захищав свою землю, яку так любив і цінував. Після війни у вересні 1967 року став засновником і організував першу виставку квітникарів-любителів у Ворошиловграді (нині Луганськ)', '/memory/p098.jpg', 98, 96),
  ('Павлов Олексій Кузьміч', 'прапрадід Дмитра Колісника', null, '/memory/p099.jpg', 99, 97),
  ('Марков Йосип Петрович', 'прапрадід Олексія Пилипенка Воював у чині полковника. Нагороди:', 'Орден Богдана Хмельницького, двократний кавалер Ордена Червоного Прапору.', '/memory/p100.jpg', 100, 98),
  ('Упир Федір Якович', 'двоюрідний дідусь Олексія Пилипенка За доблесну службу нагороджений', 'медалями За відвагу, За взяття Вени, За взяття Будапешту.', '/memory/p101.jpg', 101, 99),
  ('Мамічев Віктор Іванович', 'прадід Артема Мамічева', 'Війну розпочав у 1941 році після закінчення Качинського військово-повітряного училища. Літав штурманом на бомбардувальниках ТБ-3. Захищав місто-герой Волгоград, де був вперше збитий. В лавах І-го Українського фронту визволяв Україну. Воював у небі Донеччини, де був збитий та поранений вдруге. Визволяв Польщу, Угорщину, Австрію. Війну закінчив у Відні у званні капітана. Нагороджений орденом Бойового Червоного Прапору, двома орденами Вітчизняної Війни Іго та ІІ-го ступенів, орденом Дружби народів, орденом Трудового Червоного прапору та багатьма медалями.', '/memory/p102.jpg', 102, 100),
  ('Полянський Василь Андріанович', 'прадід Андрія Акименко', 'Воював з 1939 по 1945, дійшов до Берліна, розписався на стінах Рейхстагу як переможець. Полковник. Нагороджений орденом Вітчизняної війни І ступеня (1944) орденом Червоного Прапора (1945) медаллю За оборону Ленінграда (1942).', null, 103, 101),
  ('Неміш Юрій Петрович', 'прапрадід Данила Сидорака(справа)', 'Ще під час навчання в школі, проходив вишкіл в юнацтві Української повстанської армії, був зв’ язковим. Але в 1944 році, в 19-ти річному віці був мобілізований в ряди Радянської армії. Підготовку проходив в місті Вязьма Московської області. Воював на I Білоруському фронті у винищувальному батальйоні 75 міліметрових протитанкових гармат. З боями визволяв Білорусію, Литву і закінчив II Світову війну під Кенігсбергом (Калінінградом). Після розгрому Гітлерівської Німеччини військові з’єднання, в яких служив мій дідусь, були готові відправлятись на Далекий схід на війну проти Японії. Але атомні бомби, скинуті на Хіросіму та Нагасакі, змусили Японію капітулювати. На цьому закінчилась II Світова війна, але служба в армії продовжилась до 1951 року. Нагороджений медаллю За взяття Кенігсберга, численними ювілейними медалями та орденом Вітчизняної війни.', '/memory/p104.jpg', 104, 102),
  ('Неміш Михайло Юрійович', 'прапрадід Данила Сидорака(зліва)', 'Будучи гімназистом у 1918 році був присутнім на вічі, під час якого проголосили Західноукраїнську народну республіку. Протрималась Українська влада недовго. І десь в середині 20-х років юнак зорганізував в Чернятині першу підпільну четвірку Української військової організації (УВО). Хлопці вели протипольську агітацію. В 1929 році Михайло Неміш став членом Організації українських націоналістів (ОУН), далі районовим організаційним референтом, проводив активну просвітницьку і агітаційну роботу за відродження Української держави. В березні 1939 року всі боївки Городенківщини були готові виступити на захист Карпатської України, яка не змогли встояти перед могутнім фашистським гітлерівським блоком. В цей ж час насувалась біда зі сходу. 1940 року енкаведисти схопили Михайла Неміша і спершу засудили до розстрілу, але потім пом’якшили вирок і засудили до 16 років каторги в Сибіру і 10 років поселення на засланні. Звільнений із ГУЛАГу після смерті Сталіна, реабілітований посмертно вже за часів незалежності України.', '/memory/p105.jpg', 105, 103),
  ('Бондар Василь Петрович', 'дідусь Катерини Калінеченко', 'Бондар Василь Петрович всю війну водив «полуторку». Відомо, що перевозив їжу по Ладожському озеру «Дорогою життя» до блокадного Ленінграду. Коли у 1945 повернувся додому, у Київську область, село Лаврики одружився та мав двох синів. Любив землю, грав у сільському театрі, знав багато оповідань напам’ять, читав Кобзаря, посадив багато дерев та був бджолярем. Виноград та яблука ще досі родять і люди згадують завжди веселого та працьовитого Василя.', '/memory/p106.jpg', 106, 104),
  ('Горностай Анатолій Євтихійович', 'прадід Гліба Мікляєва', 'З березня 1944 року воюва розвідником у складі 1279 стрілецького полку 389 стрілецької дивізії Першого Українського фронту. Війну закінчив на території Німеччини в м. Дрезден. Відзначений багатьма нагородами, у тому числі орденом Червоної Зірки, медалями За відвагу, За бойові заслуги.', '/memory/p107.jpg', 107, 105),
  ('Дудник Василій Терентійович', 'прадід Гліба Мікляєва', 'У 1940 році був призваний до армії. Війну зустрів танкістом. Під Сталінградом був важко поранений у горло. Лікуючись у госпіталі, працював на тракторному заводі, де збирали танки для фронту. Воював на Другому Українському фронті. Війну закінчив у Потсдамі сержантом інженерно-технічних військ. Відзначений багатьма нагородами, у тому числі й орденом Вітчизняної війни ІІ ступеня, медалями За відвагу, За взяття Берліна, За оборону Сталінграда.', '/memory/p108.jpg', 108, 106),
  ('Дудник (П''ятакова) Євдокія Олексіївна', 'прабабуся Гліба Мікляєва', 'Під час війни мала бронь. Працювала вихователькою в Орєхово-Зуєвському цілодобовому дитячому садочку при військовому заводі. Після бомбардувань навколишніх територій збирала наляканих дітей з під завалів. Має нагороду «За доблесну працю» (1945р.).', '/memory/p109.jpg', 109, 107),
  ('Мікляєв Іван Федорович', 'Прадід Гліба Мікляєва', 'На фронті - з перших і до останніх днів війни. У 1941 році з ввіреними йому підрозділами декілька тижнів виходив з оточення. Визволяв Києв у 1943 році, за що був нагороджений орденом Червоної Зірки. Брав участь у боях за Берлін, а закінчив бойовий шлях у ІІ Світовій війні визволенням Праги у травні 1945 року. Після війни проходив службу в складі Групи радянських окупаційних військ у Німеччині до виходу у відставку. Відзначений багатьма державними нагородами.', '/memory/p110.jpg', 110, 108),
  ('Стеценко Іван Костянтинович', 'прадід Гліба Мікляєва', 'У зв’язку із тим, що був репресований у 30-і роки за пропагування української народної творчості (але, як це не дивно ще у 1938 р. реабілітований) після знаходження у катівнях НКВС був взагалі не придатний до служби в армії. Під час окупації Києва німцями був учасником антифашистського підпілля. Після визволення Радянськими військами України на початку 1944 року пішов добровольцем на фронт, де, за свідченнями радянських архівів, зник без вістіи у серпні-вересні 1944-го.', '/memory/p111.jpg', 111, 109),
  ('Стеценко (Геруха) Прасков’я Денисівна', 'прабабуся Гліба Мікляєва', 'Під час оборони Києва брала активну участь у складі народного ополчення. В окупованому німцями Києві була пов’язана з антифашистським підпіллям. Її батько, Геруха Денис, та його сім’я були заарештовані гестапо та замордовані у Дарницькому концтаборі. Але Праскові Денисівні та її чоловікові Івану Костянтиновичу разом з дітьми вдалося втекти та переховуватись від гестапо до приходу Радянських військ.', '/memory/p112.jpg', 112, 110),
  ('Богданович Йосип Максимович', 'прадід Анастасії та Ксенії Півень', 'Воював з 1944 по 1945 рр. на Першому Білоруському фронті у складі 55 запасного, 6-го та 49-го стрілецьких полків. У квітні 1945 року отримав контузію. Нагороджений орденом Вітчизняної Війни I ступеня.', '/memory/p113.jpg', 113, 111),
  ('Залевський Василь Никифорович', 'прадід Івана Ткаченка', 'Рядовий Радянської армії. Мобілізований у 1944 році. Загинув у травні 1945 року при звільнені Румунії. Довго вважався зниклим безвісти.', '/memory/p114.jpg', 114, 112),
  ('Сутула Іван Трохимович', 'дідусь Катерини Калінеченко', 'Під Сталінградом він потрапив у полон до концтабору «Шталаг 367», з якого він чудом втік. Номер на руці навіть діти його не бачили. Він завжди носив одяг з довгим рукавом. Але не дивлячись на це любив життя, постійно працював на землі на хуторі Кравчиха (Чернігівська область), мав гарну сім’ю, трьох дітей і посміхався онукам. Дідусі ніколи не розказували про війну. На 9 травня мовчки без медалей випивали чарку та плакали. Для них це не було свято «перемоги», це був нестерпний біль, що не давав загоїти рани до кінця їх життя.', '/memory/p115.jpg', 115, 113),
  ('Назаров Володимир Сергійович', 'прадід Георгія Заіки', 'Після закінчення 9-го класу пішов на фронт, пройшов дороги Великої Вітчизняної війни. З 1945 року – ревізор, перший секретар комсомолу Богуславського району Київської області. З 1950 по 1954 роки служів на флоті. Нагороджений ордерами Бойової слави ІІІ ступеня, Б. Хмельницького, Вітчизняної війни ІІ ступеня.', '/memory/p116.jpg', 116, 114),
  ('Чуєв Микола Олександрович', 'прадід Олександра Вороніна', 'Народився у 1917 році, загинув у 1941. Війна тільки почалася, німці наступали на Москву. Взводу молодих, ще недосвідчених бійців, був відданий наказ: стояти до останнього на підходах до Москви і не пускати супротивника. Атаку німців відбивав 1075 стрілецький полк, в якому воював Микола Олександрович. Він згорів у танку, захищаючи Москву.', null, 117, 115),
  ('Шередеко Петро Степанович', 'прадід Шередеко Георгія', 'Пройшов всю війну до Берліна. Був техніком-лейтенантом 260-ї Стрілкової Ковельської дивізії. Нагороджений медалями та орденом Червоної Зірки.', '/memory/p118.jpg', 118, 116),
  ('Фігура Степан Дмитрович', 'прапрадід Катерини Здебської', 'Фігура Степан Дмитрович народився в місті Короп Чернігівської області у 1897 р. У мирний час він був пічником. Війну пройшов від першого до останнього дня, завжди був на передньому краї. Дійшов до Берліна. З військових архівів батьки Катерини дізнались, що він був їздовим транспортної роти Першого Українського фронту. В архівах є запис про нагородження його орденом Червоної зірки 20 травня 1945 року.', '/memory/p119.jpg', 119, 117),
  ('Бізюра Іван Якимович', 'прадід Ольги Бізюри', 'Роки життя: 1921-1974. У 1943 вступив до лав радянської армії, воював на четвертому Українському фронті. Дійшов до Праги, отримав нагороди за її визволення. Його батько Яким весь цей час перебував у полоні у німців. Другий прадідусь, Михайло, у 1939 році пішов воювати до Польської армії, теж потрапив до полону і перебував у ньому до кінця війни. Повернувся у той час, коли на території Волині уже був Радянський союз.', '/memory/p120.jpg', 120, 118),
  ('Говоруха Борис Федорович', 'прадід Олесі Білик', 'У боях Великої Вітчизняної Війни з перших днів. Однією з основних його нагород є орден Червоної зірки. Інформація про його подвиг та нагородний лист збереглися в архівах.', '/memory/p121.jpg', 121, 119),
  ('Книш Володимир Євстахович', 'прадід Тараса Свистуна', 'У 1943 році пішов разом з іншими односельцями добровольцем на фронт. Був рядовим артилеристом у складі 4-го Українського Фронту. З боями дійшов до Польщі. Під Катовіце був поранений снайпером. Довго лікувався в госпіталі, де і довідався про капітуляцію німців та Велику Перемогу. У 1945 році повернувся у рідне село. За роки війни В. Книш здобув численні нагороди, серед яких Орден Слави II ступеня, Орден Перемоги, медаль За відвагу.', '/memory/p122.jpg', 122, 120),
  ('Коновальчук Володимир Григорович', 'прадід Богдана Гуменника', 'Артилерист, полковник. Ще у 1939 році його призвали до армії і відправили на Фінський фронт. З 1941 року пройшов війну у складі 3-го Українського фронту. Завершив війну у Болгарії. Нагороджений Орденом Червоної Зірки та 23 медалями.', '/memory/p123.jpg', 123, 121),
  ('Святченко Леонід Лаврентьйвич', 'прадід Івана Балкашинова', 'У 1941 році пішов на війну. Воював на Курській дузi. Отримав звання капітана, мав багато нагород. У 1943 році був смертельно поранений осколком гранати.', '/memory/p124.jpg', 124, 122),
  ('Алексєєв Олександр Васильович', 'двоюрідний прадід Дарії Толстанової', 'Стрілець-зенітник, з перших днів війни на фронті. Пройшов всю війну «без єдиної подряпини», дійшов до Берліна. Після перемоги був направлений в Маньчжурію. Брав участь у Радянськояпонській війні і розгромі Квантунської армії Імператорських збройних сил Японії.', '/memory/p125.jpg', 125, 123),
  ('Нечай Петро Опанасович', 'двоюрідний прадід Дарії Толстанової', 'У липні 1941 добровольцем пішов на фронт. Лейтенант, командир роти розвідників Був важко поранений, кулеметна черга прошила грудну клітку. Але не дивлячись на це продовжував воювати і повернувся додому в квітні 1945 р Нагороджений Орденом Червоної Зірки.', '/memory/p126.jpg', 126, 124),
  ('Толстанов Михайло Костянтинович(Косович)', 'прадід Дарії Толстанової', 'Лейтенант авіації, стрілокбомбардир 197 гвардійського, окремого транспортного авіаційного полку, з перших днів на фронті. Загинув разом з усім екіпажом літака ТБ-3 (важкий бомбардувальник) 24.10.1941, похований на міському кладовищі Сталінграда (Волгоград).', '/memory/p127.jpg', 127, 125),
  ('Меньшиков Григорій Пилипович', 'прадід Дарії Толстанової', 'Гвардії старший лейтенант 68 гвардійської Проскурівської Червонопрапорної стрілецької дивізії. Був призваний у березні 1942 року, учасник Сталінградської битви. На 1-му Українському фронті в битві за Дніпро отримав поранення в голову. Дійшов до Румунії. Повернувся додому 27.07.1946 Нагороджений Орденом Вітчизняної війни II ступеня, медаллю за оборону Сталінграда.', '/memory/p128.jpg', 128, 126),
  ('Мороз Іван Петрович', 'прадід Андрія Красновського', 'Війну зустрів курсантом. Бойовий шлях з 1941 по 1945, від молодшого командира до начальника ППО, пройшов у складі окремої 48-ї зенітної артилерійської бригади ППО Ленінградського фронту. Був поранений. Має нагороди, в тому числі медаль за оборону Ленінграду. Повернувся додому живим.', '/memory/p129.jpg', 129, 127),
  ('В''ячеслав Миколайович Германов', 'прадід Марії Леонтьєвої', 'Призваний на фронт у 1941 році (в 23 роки). Збройний інструктор. Воював на Білоруському фронті. Був поранений і демобілізований через поранення. У вересні 1946 року був нагороджений Орденом Вітчизняної Війни 1 ступеня.', '/memory/p130.jpg', 130, 128),
  ('Матійко Ілля Юхимович', 'прадід Ярослава Матійка', 'Єфрейтор, командир самохідної артилерійської установки. На війні з 1941 року. Брав участь у визволенні України, Білорусії, Угорщини. Нагороджений шістьма бойовими нагородами та двома грамотами Верховного головнокомандуючого.', '/memory/p131.jpg', 131, 129),
  ('Тимошенко Іван Петрович і Ганна Микитівна', 'прадід та прабабуся Андрія Карамяна', 'Тимошенко Іван Петрович у 1939 р. був призваний в ряди Радянської армії, на фронті – з 1941 по 1945. Служив штурманом в авіаційній дивізії у складі 1-го Українського фронту. Нагороджений багатьма медалями та двома орденами Червоної Зірки. Після війни продовжив службу. Демобілізований в 1958 році. Тимошенко Ганна Микитівна В 1942 році пішла на фронт разом з 4 братами, 2 з яких з війни не повернулися. Служила радисткою в авіаційній дивізії до самого кінця війни.', '/memory/p132.jpg', 132, 130),
  ('Адамович Броніслав Казимирович', 'прадід Юрія Залужного Учасник оборони Ленінграду,', 'звільнення Білорусі та Польщі. Загинув у 1944 році під польським містечком Віселівка від кулі снайпера.', '/memory/p133.jpg', 133, 131),
  ('Кравчук Василь Зінов’євич', 'прадід Юрія Залужного', 'Учасник війни з перших днів, сапер, старшина. Нагороджений орденами Червоної зірки, Слави ІІІ та ІІ ст., 18 медалями, в тому числі за форсування Дніпра, Вісли, звільнення Праги', '/memory/p134.jpg', 134, 132),
  ('Собчук Олексій Степанович', 'дідусь Марії Леонтьевої', 'В неповні 17 років пішов на фронт з військами Червоної Армії артилеристом. Пройшов війну до Берліну. Нагороджений орденом Великої Вітчизняної війни і пам''ятними медалями. Після закінчення війни служив у армії ще 7 років. Закінчив з відзнакою середню школу, Київський Політехнічний Інститут, захистив дисертацію кандидата технічних наук з теоретичних основ електромеханіки. Більше 30 років викладав у КПІ.', '/memory/p135.jpg', 135, 133),
  ('Федорців Мирослава Кіндратівна', 'прабабуся Владислава Стеця', 'Учасниця національновизвольного руху. Зв''язкова. У 2015 році указом Президента України нагороджена ордером княгині Ольги III ступеня.', '/memory/p136.jpg', 136, 134),
  ('Мудрагель Василь Данилович', 'прадід Дмитра Мудрагеля', 'Народився у с. Тарасівка Звенигородського району Київської (зараз – Черкаської) області. У 1929 році був призваний до Червоної армії в авіацію. Після закінчення школи молодших авіаспеціалістів (ШМАС) і проходження служби у частинах важкої військової авіації отримав звання технікалейтенанта. Другу світову війну прадід пройшов з першого до останнього дня. Воював на Західному фронті, брав участь в обороні Ленінграду, Сталінграду, польотах до партизанів, боях за взяття Кенігсбергу, Берліну. Закінчив війну у званні майора на посаді інженера ескадрильї. Був нагороджений орденом Бойового червоного прапора, двома орденами Червоної зірки, орденом Вітчизняної війни 1-го та 2-го ступенів, 7-ма медалями. Прослужив у Радянській армії 25 років, вийшов у відставку.', '/memory/p137.jpg', 137, 135),
  ('П’ятигорський Михайло Бенціонович', 'прадід Нікіти П‘ятигорського', 'Закінчив Київське військове училище зв’язку у 1940 році. Служив в Уральському військовому окрузі у званні молодшого лейтенанта у м. Свердловськ. В травні 1941 у складі дивізії був відправлений на західний кордон СССР під м. Вітебськ, де прийняв перший бій з військами німецьких загарбників. Разом зі штабом армії потрапив в оточення, з якого виходили два місяці, зберігши прапор дивізії. Воював у складі Білоруського, а згодом, 2-го Українського фронтів. Завідував пересувною радіоустановкою, за допомогою якої велась пропаганда на передові німецькі позиції. Пройшов з боями Україну, Білорусь, Польщу, Чехословаччину. Закінчив війну у Берліні. Був нагороджений під час війни орденом Червоної Зірки, орденом Червоного Прапора, орденом Вітчизняної Війни II ступеня.', '/memory/p138.jpg', 138, 136),
  ('Артюх Яків Антонович', 'дідусь Максима Хижняка', 'Під час Великої Вітчизняної Війни у 1942 році отримав вищу ступінь відзнаки – Героя Радянського Союзу. Цю нагороду Василь Кузьмич отримав за подвиг на території Криму. Він дістав для розвідки дані про розташування військ фашистських окупантів. Завдяки цим даним радянські війська правильно спланували напад і виграли битву. Він ризикував життям, провів три дні без їжі і просидів кілька годин у колодязі, дихаючи через соломинку. За цей подвиг він отримав медаль “Золота зірка”. Йому було 18 років. На фото Рижов Яків Антоновичз дружиною Ганною', '/memory/p139.jpg', 139, 137),
  ('Артюх Яків Антонович', 'дідусь Максима Хижняка', 'Народився на Чернігівщині (1925-2008) По досягненню 18 років влітку 1943 року був призваний в армію. Восени 1943 року під час форсування Дніпра в складі артилерійського підрозділу був вперше тяжко поранений. Нагороджений медаллю “За визволення Києва”. Брав участь у визволенні Угорщини, Польщі, Чехословаччини. День Перемоги зустрів у госпіталі в Празі після другого тяжкого поранення. Після закінчення війни повернувся в рідне село і працював до пенсії', '/memory/p140.jpg', 140, 138),
  ('Свирид Григорій Васильович', 'Свирид Ольга Петрівна – прадід та прабабуся Нікіти Негуляєва', 'Свирид Григорій Васильович брав участь у битві за Москву в складі легендарних сибірських військ. Отримав тяжкі поранення в жорстокому бою під Москвою взимку 1941 р. Був демобілізований за інвалідністю. Далі працював у тилу. Свирид Ольга Петрівна брала участь у бойових діях на Воронежському фронті у складі медсанбату санітаркою. Була поранена в бою у 1942 році. Демобілізована по інвалідності.', null, 141, 139),
  ('Негуляєв Олександр Порфирійович', 'Негуляєв Олексій Порфирійович – прадід та його брат Нікіти Негуляєва', 'Олександр Порфирійович воював у складі саперних військ. Пройшов всю війну. Брав участь у Корсунь-Шевченківській битві. Олексій Порфирійович був льотчиком. Загинув в перший рік війни. В його честь назвали дідуся, який народився у 1942 р. – Олексієм.', null, 142, 140),
  ('Омельчук Федір Антонович', 'Омельчук Наталія Андріївна – прадід та прабабуся Яна Шкури', 'Федір Антонович та Наталія Андріївна в мирний час працювали вчителями. На початку Великої Вітчизняної війни місцевим партійним осередком було прийняте рішення залишити їх на окупованій території для здійснення розвідницької та диверсійної діяльності. Вони були членами підпільного угрупування партизанського загону, що вів боротьбу з німецько- фашистськими загарбниками на території Хмельниччини. Брали участь у багатьох диверсійних операціях проти окупантів. Зокрема, врятували велику кількість молоді від відправки на примусові роботи в Німеччину та концентраційні табори. Були викриті. Дивом уникли розстрілу. Федір Антонович був вивезений до концентраційного табору. Повернувся. Після закінчення Другої Світової війни Федір Антонович і Наталія Андріївна продовжили викладацьку діяльність та виховали сотні чудових фахівців.', null, 143, 141),
  ('Тищенко Михайло Іванович', 'прадід Владислава Декрета', 'У перші дні війни був призваний в армію і направлений на Південний фронт, де воював у знаменитій Чапаєвській дивізії. Війна для нього почалася у Севастополі. У боях на острові Херсонес попав у полон. По дорозі у Німеччину зумів втекти і повернутись у Недру. У 1943 р. був призваний в діючу армію. Брав участь у форсуванні Дніпра в районі села Петривці, де був поранений. Після лікування у госпіталі визволяв Румунію, Угорщину, Австрію, Чехословаччину. Нагороджений двома орденами Слави та медалями. Після війни працював учителем Недрянської середньої школи.', '/memory/p144.jpg', 144, 142),
  ('Осінчук Петро Григорович', 'прапрадід Богдана Нікітіна', 'У березні1944р. був мобілізований до радянської армії. Після закінчення навчання залишили викладачем військового училища. Зимою 1945р.був направлений на Другий Український фронт, де служив зв’язковим в артилерії. За кілька днів до офіційної капітуляції Німеччини був тяжко поранений на території Польщі і помер у воєнному шпиталі 30 травня 1945р. Похований на військовому цвинтарі у м. Легніца. Загинув на фронті і його двоюрідний брат Осінчук Святослав 1926 р. народження, єдиний син у сім’ї. Його батько також був мобілізований до армії, але повернувся живим. Другий двоюрідний брат Олександр Пилипович, 1920р. народження, був станичним ОУН, згорів живцем у підпаленій органами НКВС і НКДБ хаті, а його родину вивезли до Архангельської області (Росія).', '/memory/p145.jpg', 145, 143),
  ('Попов Петро Осипович', 'прадід Богдана Нікітіна', 'Під час Другої Світової Війни пройшов шлях від Західного до Східного фронту, отримав звання «Герой битви на Халхин- Голі». По завершенні трагічних подій прадід Петро, як кадровий офіцер прикордонних військ на Далекому Сході закінчив службу у званні майора та був нагороджений численними нагородами за бойові заслуги. По закінченні війни Петро Осипович працював вчителем історії, директором школи та головою обласної спілки ветеранів Великої Вітчизняної війни.', '/memory/p146.jpg', 146, 144),
  ('Попов Петро Осипович', 'прадід Богдана Нікітіна', 'Під час Другої Світової Війни пройшов шлях від Західного до Східного фронту, отримав звання «Герой битви на Халхин- Голі». По завершенні трагічних подій прапрадід Петро, як кадровий офіцер прикордонних військ на Далекому Сході закінчив службу у званні майора та був нагороджений численними нагородами за бойові заслуги. По закінченні війни Петро Осипович працював вчителем історії, директором школи та Головою обласної спілки ветеранів Великої Вітчизняної війни.', '/memory/p147.jpg', 147, 145),
  ('Зайцевська (Дорохова) Ольга Петрівна', 'прабабуся Богдана Нікітіна', 'У травні 1941 року закінчила Воронезький медичний інститут. Після початку війни 22 червня 1941 року була мобілізована в армію лікарем польового шпиталю.. В польових умовах змогла налагодити пряме переливання крові, що дало змогу вижити багатьом бійцям. Почала війну на Воронезькому фронті, разом з ним відступала до Сталінграда. З наступом Радянської армії через Естонію потрапила до Східної Пруссії під місто Кенігсберг. Після капітуляції Німеччини її з військовими перекинули на Японський фронт в Маньчжурію. Під кінець війни Ольга Петрівна мала звання капітана медичної служби. Нагороджена орденом «Червоної Зірки» та медалями «За перемогу над Німеччиною», «За взяття Кенігсбергу», «За перемогу над Японією», «За відвагу». Після війни вона продовжила роботу лікарем. Померла зі званням полковника запасу медичної служби у 92 роки.', '/memory/p148.jpg', 148, 146),
  ('Оселедько Артем Семенович', 'прадід Даніїла Мандрики', 'Роки життя: 1902-1969рр. Відомо, що воював в Польщі і там потрапив у полон.', '/memory/p149.jpg', 149, 147),
  ('Луговська Степанида Антонівна', 'прабабуся Дмитра Тарана', '1920 року народження. Була мобілізована на фронт з перших днів війни медсестрою. Служила в прифронтовому потязі, який евакуював поранених з передової до госпіталю. Закінчила війну старшим лейтенантом у Відні в листопаді 1945р. Після війни працювала акушеркою у пологовому будинку до 1992р. Прийняла більше 25000 новонароджених.', '/memory/p150.jpg', 150, 148),
  ('Коваленко Андрій Михайлович', 'дідусь Владислава Шимоновича', 'У 18-річному віці був прийнятий до Харківського авіаційного училища. По закінченню брав безпосередню участь у боях у складі льотного екіпажу 597-го авіаційного полку 208-ї Київської Червонопрапорної авіадивізії 2-ої Повітряної армії. Здійснив більше 400 бойових вильотів. Під час Корсунь- Шевченківської битви був збитий зенітним вогнем на ворожій території, літак впав у ліс, де згодом його знайшли партизани та врятували екіпаж. Під час війни Андрій Михайлович був неодноразово поранений, контужений.', '/memory/p151.jpg', 151, 149),
  ('Дуденко Парасковія Іванівна', 'прабабуся Дар’ї Проніної', 'Служила з лютого 1944 р. до травня 1945 р. завідуючою діловодством продовольчо-фуражної служби госпіталю легко поранених №5547 Другого Українського фронту. Перемогу зустріла в Празі. Нагороджена багатьма відзнаками, в тому числі й орденом Вітчизняної війни ІІ ступеню, медаллю За відвагу.', '/memory/p152.jpg', 152, 150),
  ('Бутенко Іван Юхимович', 'прадід Геннадія Ольшаного', 'З 1941 р. був на фронті, на передовій. Службу проходив у 106 стрілецькому корпусі 4-го Українського фронту. Пройшов усю війну, був нагороджений Орденом Слави ІІІ ступеня. Війну завершив учасником “Празької операції”, де забезпечував зв’язок для штабу фронту. Повернувся додому живим.', '/memory/p153.jpg', 153, 151),
  ('Степан Мудрик', 'Мечник – дід Захарія Покотила', 'Член Головного проводу ОУН, однодумець і помічник Степана Бандери, в''язень німецьких концтаборів, засуджений на кару смерті. Керівник розвідки закордонних частин ОУН. Голова Головної Ради ОУН, заступник президента Світового конгресу вільних українців в Європі. Нагороджений найвищою нагородою Товариства колишніх вояків УПА — «Золотим Хрестом». Письменник, публіцист, політолог.', '/memory/p154.jpg', 154, 152),
  ('Веселовський Лоллій Олександрович', 'дідусь Олексія Молодчика Мріяв стати художником, але сталася війна…', 'У 14 років вступив до спеціальної військової морської школи, в якій готували зміну для фронту. А у 16 – фронт і …кінець війні. Але обраний шлях вже не змінив і пройшов від матроса до командира військової частини: три дипломи вищої освіти, два свідоцтва майстра спорту і, головне, добра пам''ять багатьох людей, у долі яких він брав участь…', '/memory/p155.jpg', 155, 153),
  ('Авраменко Володимир Пилипович', 'прадід Юлії Філь', 'Народився у 1918 р. Війну зустрів на службі. Був направлений у місто Сейм, де потрапив до батальйону аеродромного забезпечення (БАЗ). На БАЗ неодноразово здійснювалися нальоти ворожої авіації. Пройшов усю війну, звістку про перемогу отримав на Білоруському фронті, а по закінченню війни йому було присвоєне офіцерське звання.', '/memory/p156.jpg', 156, 154),
  ('Стрельнікова Ганна Яківна', 'прабабуся Юлії Філь', 'Народилася у 1924 р. Коли розпочалася війна, вона 17-тирічною дівчиною записалась добровольцем до лав Червоної Армії, “приписавши” собі один рік. ЇЇ направили на курси радистів, а по закінченню – до винищувального авіаційного полку у підрозділ зв’язку, який забезпечував надійний наземний і повітряний радіозв’ язок.', '/memory/p157.jpg', 157, 155),
  ('Крошин Микола Петрович', 'прадід Анастасії Давидової', 'Брав участь у радянськофінській війні. З перших днів Великої Вітчизняної Війни пішов на фронт. Був тяжко поранений (осколок пройшов на відстані 2 мм від серця). У 1944 році визволяв Західну Україну. Перемогу зустрів у Румунії. Нагороджений медалями «За Відвагу» та «За бойові заслуги».', '/memory/p158.jpg', 158, 156),
  ('Микола Ілларіонович Андрійченко', 'прадід Артема Кравченко', 'Під час війни був командиром гарматного підрозділу у 1058-й артилерійському полку. Брав участь у боях від Сталінграду до Берліну. Під час наступу німецьких військ під командуванням Еріха фон Манштейна в районі Сталінграду був важко поранений. Був нагороджений багатьма орденами та медалями.', '/memory/p159.jpg', 159, 157),
  ('Івашкевич Леонід Олександрович', 'прадід Семена Івашкевича', 'У 1941 році був призваний у лави Радянської армії, на початку війни служив на кордоні Білоруської РСР артилеристом. Частина, у якій служив, була повністю розбита. Під час наступу Червоної армії дійшов до Берліну, Нагороджений бойовими відзнаками, медалями. Два брати Леоніда служили у партизанських загонах, загинули під час війни, а ще один - Михайло - служив на Далекому Сході, став професійним військовим', '/memory/p160.jpg', 160, 158),
  ('Кривохижа Микита Матвійович', 'прадід Романа Кривохижи', 'Кривохижа М.М. був мобілізований та відправлений на кордон, неподалік міста Перемишль. З боями відступив до Кременчука, отримав поранення й потрапив у полон, але йому вдалось втекти. Потрапивши до своїх, був знову мобілізований. Після боїв на Лютізькому плацдармі був перекинутий на Ленінградський фронт. Брав участь у взятті Кенінгсберга та боях під Теуелі та Мірені. Після двох поранень був направлений у Київський госпіталь. 9 травня зустрічав у колі родини.', '/memory/p161.jpg', 161, 159),
  ('Сімонов Михайло Сергійович', 'прадід Варвари Лемешевої', 'Служив у лавах Другого Українського фронту в інженерних військах (понтонне з’єднання). Пройшов усю війну.', '/memory/p162.jpg', 162, 160),
  ('Байдужий Яків Павлович', 'прадід Івана та Петра Жолнерів', 'Пройшов усю війну, брав участь у Берлінській операції. Службу розпочинав рядовим солдатом піхоти, згодом дослужився до розвідника. Мав 3 поранення. Нагороди: Орден Слави ІІІ ступеня; Орден Слави ІІ ступеня; Медаль за взяття Варшави; Медаль за відвагу; Медаль за бойові заслуги.', '/memory/p163.jpg', 163, 161),
  ('Лебедів Кирило Олександрович', 'прадід Дмитра Лиховського', 'В вересні 1941 року вважався безвісти зниклим. З вересня 1941 р. по квітень 1942 р. перебував в концтаборі в Польщі. Був розстріляний в квітні 1942 року. Похований в Польщі в братській могилі.', '/memory/p164.jpg', 164, 162),
  ('Сосіновська Ніна Євгенівна', 'прабабуся Максима Шлямара', 'Льотчиця. Пройшла усю війну, перевозила літаком вантажні машини на фронт. Брала участь у звільненні Ленінграду. Нагороджена медаллю За звільнення Ленінграда', '/memory/p165.jpg', 165, 163),
  ('Кузьміна Лідія Григорівна', 'прабабуся Максима Шлямара', 'Лейтенант медичної служби. Служила у лавах Першого Ленінградського фронту. Була начальником медичного забезпечення фронту, пройшла усю війну.', '/memory/p166.jpg', 166, 164),
  ('Кузьмін Марк Євстратьєвич', 'прадід Максима Шлямара', 'Воював під Смоленськом, потрапив у концтабір у Польщі, після звільнення з табору дійшов з боями до Берліну', '/memory/p167.jpg', 167, 165),
  ('Пичко Павло Якович', 'дідусь Єлизавети Борисенко', 'До війни працював інженером-конструктором. Брав участь у визволені Києва. Нагороджений орденами Червоної Зірки та Вітчизняної Війни1го ступеня.', '/memory/p168.jpg', 168, 166),
  ('Борисенко Діна Арсентіївна', 'бабуся Єлизавети Борисенко', 'Пішла на фронт медсестрою, сама була поранена осколками снаряду. У званні сержанта медичної служби брала участь у визволенні міст Біла Церква, Могилів - Подільський та інших, у звільненні Трансільванії, в ліквідації Корсунь – Шевченківського та Уманського угруповань німців, у форсуванні річки Дністер, в утриманні плацдарму на західному березі Дунаю. Нагороджена орденом Вітчизняної війни 2 ступеня та медаллю За відвагу', '/memory/p169.jpg', 169, 167),
  ('Головаш Софія Андріївна та Андрій Платонович', 'бабуся та дідусь Єлізавети Борисенко', 'Софія Андріївна підлітком потрапила на війну, разом з матір''ю Вірою Миколаївною працювала на військово-польовій кухні. У складі діючої армії дійшла до Берліна, у дні Перемоги разом з іншими солдатами розписалася на стінах Рейхстагу. Нагороджена численними медалями, у тому числі медаллю «За перемогу над Німеччиною». Андрій Платонович у складі Першого Білоруського фронту під командуванням генерала К.К. Рокосовського брав участь у визволенні Білорусі, Польщі, у битві за Берлін. Був поранений і після війни отримав інвалідність 1 групи. Нагороджений двома орденами Вітчизняної війни, двома орденами Червоної Зірки, а також медалями За взяття Берліна та За бойові заслуги.', '/memory/p170.jpg', 170, 168),
  ('Сапун Василь Степанович', 'дідусь Олексія Дьоміна', 'Уродженець Полтавщини. Через польовий військкомат 18-річний юнак добровільно пішов на фронт. У 1943 - 1945 роках брав безпосередню участь у боях на 3-му Українському фронті рядовим солдатом – артилеристом. Воював під Харковом і Києвом , у районі Ясс, і в Угорщині. В одному з тяжких боїв в Угорщині, в районі озера Балатон був важко контужений, після семи місяців лікування в госпіталях був демобілізований. Василь Степанович має бойові нагороди: орден Слави 1 ступені, орден Вітчизняної війни 1 і 2 ступені, багато медалей.', '/memory/p171.jpg', 171, 169),
  ('Дьомін Ісак Львович', 'дідусь Олексія Дьоміна', 'У 1940-му році був призваний на службу в Червону Армію. Зустрів війну на Західній Україні під містом Рівне. Три роки воював зв''язківцем у піхоті. А в листопаді 1943р. рідні отримали сповіщення про те, що рядовий Дьомін І. Л. пропав безвісти ...', '/memory/p172.jpg', 172, 170),
  ('Гороховский Григорій Ізраілевич', 'прадід Івана Гороховського', 'На початку війни був студентом . Пережив блокаду в Ленінграді, був бійцем винищувального батальйону. У 1942 році призваний в діючу армію. Був командиром шабельної роти, командиром мінометного взводу. У 1944 р. визволяв Західну Україну. Після війни служив у десантних військах. Нагороджений багатьма медалями і орденами, у їх числі: медалі За оборону Ленінграду, За військові заслуги, два ордени Великої вітчизняної війни.', '/memory/p173.jpg', 173, 171),
  ('Мартиненко Петро Мойсейович', 'батько вчителя Рустамової В.П.,', 'прадід Жанни Стеч Військове звання – старшина. Призваний на військову службу 6 вересня 1939р., службу проходив на Далекому Сході. З червня 1941 року по травень 1945 року у складі 413 автотранспортного батальйону, 42 відділення брав участь у боях. З серпня 1945 року по вересень 1945 року воював з Японією, демобілізований 6 червня 1946 року. Нагороджений Орденом Вітчизняної війни, медалями За відвагу, За перемогу над Японією.', '/memory/p174.jpg', 174, 172),
  ('Мартиненко Генадій Мойсейович', 'дядько вчителя В.П.Рустамової, прадід Жанни Стеч', 'Призваний на військову службу у 1940 році. Воював з 1941 по 1944 рік. У 1944 році комісований через поранення. Нагороджений Орденом Вітчизняної війни, медаллю За відвагу, За мужність.', '/memory/p175.jpg', 175, 173),
  ('Усков Іван Павлович', 'дідусь Тетяни Василівни Сагайдак', 'З перших днів війни пішов на фронт. Дійшов до Берліна. Був поранений. Нагороджений медалями Перемога над Німеччиною, За відвагу, подякою від Верховного Головнокомандуючого.', '/memory/p176.jpg', 176, 174),
  ('Сагайдак Анатолій Данилович', 'свекор Тетяни Василівни Сагайдак', 'З 16 років пішов на фронт. Визволяв Європу та Німеччину від фашизму. Нагороджений багатьма медалями, в тому числі медаллю За бойові заслуги.', '/memory/p177.jpg', 177, 175),
  ('Чернецький Станіслав Віталійович', 'дідусь Анастасії Махоткіної Був мобілізований до Червоної Армії ще', 'студентом у 1941 році. Був артилеристом. Під час відступу зміг урятувати усю документацію канцелярії свого полку, за що отримав нагороду, яка знайшла його через 30 років після Перемоги. У 1943 отримав тяжке поранення.', '/memory/p178.jpg', 178, 176),
  ('Кутовий Іван Васильович', 'дід Поліни ІванівниТрояновської', 'Учасник Другої Світової війни. Був активним членом Новомосковської підпільної організації з 1941 року, а з 1943 року її секретарем. Його дружина, Кутова Поліна Іванівна, також була членом Новомосковської підпільної організації. Підпільним комітетом були організовані диверсійні акти, мінування мостів, вивід із робочого режиму механізмів заводів, листівками закликали народ виявляти непокору фашистськими загарбниками. В ніч з 17 на 18 серпня 1943 року майже всіх членів підпільної організації було заарештовано Дніпропетровським гестапо. На допитах заарештованих жорстоко катували. Майже два місяці Іван Васильович провів у застінках гестапо. Пролунав вирок гестапо: «Страта. Розстріл. Спалення». В записці до дружини з затінків гестапо він писав: «Я не вмираю. Моє майбутнє – це моя дитина. Якщо син – то тільки Іван». За особисту мужність і відвагу у боях з ворогами країни під час Великої Вітчизняної війни Кутова Поліна Іванівна та Іван Васильович Кутовий медаллю «За відвагу» нагороджені посмертно.', '/memory/p179.jpg', 179, 177),
  ('Нечаєв Микола Арсентійович', 'прадід Вероніки Нечаєвої та Людмили Мордвінцевої', 'Воював у 1941-1942 в піхоті, дивом врятувався з оточення. Комісований з двома пораненнями ніг. Після війни працював бухгалтером пересувної будівельної колони.', '/memory/p180.jpg', 180, 178),
  ('Царегородцев Микола Якович', 'прадід Людмили Мордвінцевої', 'З викладацької діяльності був мобілізований на військову службу червоноармійцем у 1940 році і прослужив в лавах Радянської Армії 20 років. З початку війни служив у складі окремого кавалерійського полку. За наказом військового командування у 1943 році як фахівець-офіцер повернувся до викладацької діяльності. Микола Якович нагороджений орденом Червоної Зірки, медалями За доблесну працю у Великій Вітчизняній Війні, Захиснику Вітчизни, а також багатьма іншими військовими та трудовими нагородами та відзнаками.', '/memory/p181.jpg', 181, 179),
  ('Бернштейн Петро Борисович', 'прадід Олександра Макарчука', 'У якості фотокореспондента, у складі Білоруського фронту дійшов до Берліну. Брав участь в боях і був двічі поранений. Автор фотографії “Дві матері”.', '/memory/p182.jpg', 182, 180),
  ('Коваленко Андрій Михайлович', 'дідусь Владислава Шимоновича', 'У 18-річному віці був прийнятий до Харківського авіаційного училища. Закінчивши його, брав безпосередню участь у боях у складі льотного екіпажу 597-го авіаційного полку 208-ї Київської Червонопрапорної авіадивізії 2-ої Повітряної армії. Здійснив більше 400 бойових вильотів. Під час Корсунь-Шевченківської битви був збитий зенітним вогнем на ворожій території, літак впав у ліс, де згодом його знайшли партизани та врятували екіпаж. Під час війни Андрій Михайлович був неодноразово поранений, контужений. Має бойові нагороди.', '/memory/p183.jpg', 183, 181),
  ('Бомбін Сергій Федорович', 'прадід Івана Рамика', 'У 17років, приписавши собі рік, вступив до льотного училища. Після його закінчення був направлений на фронт. Пройшов усю війну. Нагороджений двома орденами Слави, орденом Червоної Зірки та медалями За бойові заслуги, За взяття Відня, За взяття Берліна.', '/memory/p184.jpg', 184, 182),
  ('Мандрика Федір Іванович', 'прадід Даниїла Мандрики', 'Брав участь у бойових діях під час війни. Закінчив війну у 1945 році у Чехословаччині', '/memory/p185.jpg', 185, 183),
  ('Кирилюк Федір Андрійович', 'прадід Даниїла Мандрики Пройшов всю війну. Воював артилеристом. Був', 'поранений під Ленінградом. Брав Берлін, розписався на будівлі Рейхстагу. Закінчив воювати в 1945 в Німеччині. Має 2 медалі: За відвагу, За взяття Берліну.', '/memory/p186.jpg', 186, 184),
  ('Ладний Іван Серапіонович', 'прадід Владислава Берестяного', 'Був призваний до лав армії у 1941р. Пройшов війну артилеристом. У 1944 був поранений. Нагороджений орденом За мужність.', '/memory/p187.jpg', 187, 185),
  ('Кириченко Валентин Олексійович', 'прадід Богдана Кириченко', 'У 1943р. поступив в Ленінградське авіатехнічне училище, яке в той час було евакуйоване до Новокузнецку. По закінченню училища був направлений на службу на один з військових аеродромів Брянської області, де і служив до кінця війни. Нагороджений Орденом За мужність III ступеня та медалями.', '/memory/p188.jpg', 188, 186),
  ('Гуревич Олександр', 'прадід Євгена Самаріна', 'Ще до війни після 7 класу вступив до артилерійського училища. З початком війни разом з училищем був евакуйований до Башкирії. Після закінчення училища молодшим лейтенантом воював у Білорусії. Загинув 8 січня 1944. Похований на території Білорусії у братській могилі.', '/memory/p189.jpg', 189, 187),
  ('Абугов Григорій Михайлович', 'прапрадід Євгена Самаріна', 'Мобілізований у липні 1941року в званні старшого політрука, воював у піхоті на території Північного Кавказу, Закавказзя, України, Австрії, Угорщини. Брав участь у визволенні Києва, демобілізований у лютому 1946 році в званні майора. Має нагороди: ордена «Вітчизняної війни» 1 ст., «Вітчизняної війни» 2 ст., «Червоної Зірки», медалі «За оборону Кавказу», «За взяття Будапешта» «За перемогу над Німеччиною у Великій війні 1941-1945 рр.»', '/memory/p190.jpg', 190, 188),
  ('Абугов Олександр Григорович', 'прадід Євгена Самаріна', 'У 17 років був призваний до РККА. Після 3-місячних курсів з листопада 1943 воював рядовим артилерії на території України, Румунії, Угорщини. Після війни продовжував служити на Західній Україні (Берегово, Виноградово). Демобілізований у званні єфрейтора в серпні 1950 року. Нагороджений медаллю «За перемогу над Німеччиною у Великій Вітчизняній війні 1941-1945 р.р.»', '/memory/p191.jpg', 191, 189),
  ('Бородіна Ніна Степанівна', 'прабабуся Олександра Лісніченко', 'По закінченню школи вступила до медичного училища, яке закінчила у червні 1941-го року. І в серпні 1941го була зарахована до складу однієї з медичних частин Другого Українського фронту. При переміщенні поранених у складі медичного поїзда з Червоним Хрестом потрапила під бомбардування, була контужена. З Другим Українським фронтом Ніна Степанівна закінчила війну у 1945 році в Будапешті. До середини 1946 служила в медичній частині у Відні. Нагороджена численними орденами і медалями за заслуги перед Батьківщиною.', '/memory/p192.jpg', 192, 190),
  ('Чайка Михайло Андрійович та Чайка Олександра Іванівна', 'прадід та прабабуся Дмитра Тарана', 'Михайло Андрійович почав війну у 1941 році командиром танкового взводу, брав участь в танкових боях під Москвою, приймав на озброєння та перший вів у бій танки Т-34. Мав тяжкі поранення Закінчив війну героєм у 1943 році. Олександра Іванівна із самого початку війни в 17 років пішла на фронт добровольцем. Брала участь в обороні Москви кулеметницею протиповітряної оборони. Закінчила війну в 1945 році.', '/memory/p193.jpg', 193, 191),
  ('Линник Федір Герасимович', 'прадід Антона Главіна', 'Спочатку військова частина Федора Герасимовича брала участь в обороні Одеси, а згодом були перекинуті на захист Севастополя. Билися до останнього патрона - з берданками проти кулеметів і автоматів. Їх відтіснили до Херсонесу. Федір Герасимович вижив і тут, з боєм пішов з Херсонеса і ще два тижні продовжував битися після здачі міста. Родина чекала його, незважаючи на похоронку від 12.VI.1942р. А він всупереч похоронці дійсно був ще живий до кінця грудня 1942р., поки не був замучений каторжною працею, голодом, холодом і побоями у концтаборі "Lamsdorf" у Польщі .', '/memory/p194.jpg', 194, 192),
  ('Чепинога Ольга Петрівна', 'Шейнкман Еммануїл Абрамович – прабабуся і прадід Антона Главіна', 'На фотографії - Ольга Петрівна і Еммануїл Абрамович в день закінчення санітарно-гігієнічного факультету Київського медінституту. Працювали до війни дослідникамибіохіміками, обидва були на фронті. Еммануїл Абрамович пішов на війну добровольцем в перші ж її дні, був лікарем фронтового госпіталю. Загинув в оточенні під Харковом. Ольга Петрівна також була лікарем госпіталю, спочатку евакуаційного, потім і фронтового. Як і її чоловік, побувала в оточення на Кавказі, з якого їй вдалося вийти.', '/memory/p195.jpg', 195, 193),
  ('Короленко Микола Антонович', 'прадід Андрія Чумака', '. Воював з першого до останнього дня. Був розвідником в артилерійському полку. Захищав Ленінград під час Ленінградської блокади. Закінчив війну в Німеччині в складі 1-го Українського фронту. Отримав два поранення, одне з них важке. Нагороджений бойовими нагородами: орденом «Червоної зірки», орденом «Вітчизняної війни», медаллю «За відвагу», а також пам''ятними медалями: «За перемогу над Німеччиною», «За оборону Ленінграда» та іншими.', '/memory/p196.jpg', 196, 194),
  ('Величко Валентин Юхимович', 'прадід Михайліни Любимої', '1921 року народження. До лав радянської армії був призваний 1940 року. Служив на Далекому сході, був механіком з обслуговування військових літаків. У 1943 після Сталінградської битви направлений до військового училища в Підмосков''я. Після закінчення військових курсів потрапив на фронт. З боями пройшов усю Європу, перемогу зустрів неподалеку від Берліна. Після закінчення війни працював фельдшером, був головою сільради, депутатом місцевих рад; грав в аматорських гуртках, співав, захоплювався шахами, вирощуванням винограду, розведенням кролів та лозоплетінням.', '/memory/p197.jpg', 197, 195),
  ('Андрійченко Микола Іларіонович', 'прадід Миколи Кравченко', 'Брав участь у Сталінградській битві у складі 1058-го артилерійського полку. Битва була дуже важкою і кровопролитною. Гармата, якою командував Микола Іларіонович, тільки в одному бою знищила 13 німецьких танків. У тих боях старшина був важко поранений. Після Сталінградської битви Микола Іларіонович брав участь у Курській битві, визволяв від німецько-фашистських загарбників Україну, Польщу, дійшов до Берліна, де зустрів Перемогу. За свої воїнські подвиги був нагороджений багатьма бойовими орденами та медалями.', '/memory/p198.jpg', 198, 196),
  ('Іващук Дмитро Семенович', 'прадід Дар’ї Проніної', 'Воював з часу звільнення Правобережної України до Перемоги у складі 46-ої окремої стрілецької Новгородської Червонопрапорної бригади Першого Білоруського фронту. Молодший сержант, кулеметник. Війну закінчив на території Австрії. Відзначений багатьма нагородами, в тому числі й орденом Вітчизняної війни ІІ ступеня, медаллю за перемогу над Німеччиною у ВВВ.', '/memory/p199.jpg', 199, 197),
  ('Биченко Ганна Костянтинівна', 'прабабуся Владислава Декрета', 'В перші дні війни Ганна Костянтинівна добровільно пішла на фронт. Була головним лікарем на фронті. Службу закінчила в Угорщині у жовтні 1945-го після розформування їхньої частини. За хоробрість, стійкість і мужність, проявлені в боротьбі з фашизом, нагороджена орденами Великої Вітчизняної війни 2 ступеня та орденом Богдана Хмельницького, багатьма медалями, а також у 1966 році - орденом Леніна', '/memory/p200.jpg', 200, 198),
  ('Невірівський Олександр Алоїзович', 'брат бабусі Сергія Роде', 'Народився в 1905 році у Воронізькій губернії, онук польського шляхтича, який брав участь у повстанні 1863 року і був засланий на Сибір і нащадок дворян Російської імперії. В 20-х рр. переселився з сім’єю на Алтай (Зирянівськ, Усть-Каменогорськ і т.д.). Сім’я страшно бідувала, постійно ходили голодні. У 1920-1930х рр. працював викладачем у школах, вчився у вчительському інституті. У 1942 році призваний на фронт з міста Кара-Балта у Киргизії, командир роти 19 Фрунзенської Окружної школи снайперів. Потрапив у 16 штафбат. 15.08.1943 року загинув на Смоленщині. Поновлений у правах і званнях посмертно.', '/memory/p201.jpg', 201, 199),
  ('Бублик Данило Павлович', 'прадід Сергія Роде', 'Народився в 1915 році у селі Капустинці на Яготинщині, нащадок старих козацько-християнських родів краю. Рідний брат красного козака Української Республіки 1920х рр. Кузьми Бублика (1901-1925), трагічно загиблого у 24 роки. Пережив голодовку 1932-1933 рр. У 1930х навчався у технікумі громадського харчування, призваний у війська НКВС на строкову службу, яку проходив у Львівській області. 1 липня 1941 року загинув поблизу станції Бережани Львівської області за нез’ясованих обставин. Залишилась жінка і син (1941 р.н.), який у 1970х рр. загинув на кордоні СРСР', '/memory/p202.jpg', 202, 200),
  ('Бублик Іван Павлович', 'прадід Сергія Роде', 'Народився у 1918 році у селі Капустинці на Яготинщині, нащадок старих козацько-християнських родів краю. Рідний брат красного козака Української Республіки 1920х рр. Кузьми Бублика (1901-1925), трагічно загиблого у 24 роки. Пережив голодовку 1932-1933 рр. У 1930х навчався у льотному училищі, потім перейшов на службу у війська НКВС. У 1940х рр. служив заступником начальника відділу контррозвідки СМЕРШ 61 Армії Першого Білоруського фронту. Після війни закінчив юридичний факультет і працював юристом при аеродромі.', '/memory/p203.jpg', 203, 201),
  ('Бублик Семен Павлович', 'прадід Сергія Роде', 'Народився в 1909 році у селі Капустинці на Яготинщині, нащадок старих козацькохристиянських родів краю. Рідний брат красного козака Української Республіки 1920х рр. Кузьми Бублика (1901-1925), трагічно загиблого у 24 роки. Пережив голодовку 1932-1933 рр. У 1930х навчався у Інституті сільського господарства в Києві, потім в аспірантурі, в 1941 році захистив кандидатську дисертацію. Пройшов всю війну від Сталінграда до Берліна (“всю Європу на пузі проповз”). Закінчив війну 9 травня 1945 року у Берліні, 2 роки його відбудовував. Потім викладав, займався наукою, доцент і зав. кафедри у Інституті с.г. в Києві. Помер у 1995 році.', '/memory/p204.jpg', 204, 202),
  ('Деревець Володимир Антонович', 'родич Сергія Роде', 'Народився у 1920 році в містечку Гоголів Остерського повіту Чернігівської губернії Української Республіки (нині Броварський район Київської області. Нащадок старих козацькохристиянських родів краю. Одружений, жінка Анастасія Василівна. У 1941 році потрапив у полон. Перебував у концтаборах, звідки утік у 1944 році. Застрелений на наступний день після втечі.', '/memory/p205.jpg', 205, 203),
  ('Бублик Яків Павлович', 'прадід Сергія Роде', 'Народився в 1905 році у селі Капустинці на Яготинщині, нащадок старих козацько-християнських родів краю. Рідний брат красного козака Української Республіки 1920х рр. Кузьми Бублика (1901-1925), трагічно загиблого у 24 роки. У 1930-1940х навчався у КНУ ім. Т.Г. Шевченка, біологічний факультет. Пережив голодовку 1932-1933 рр. і репресії 1937-1939 рр. В 1941 році залишився у рідному селі. Викладав у школі рідного села під час і після окупації біологію і хімію, багато випускників (в т.ч. академік), які досі згадують його науку добрим словом. Довгожитель, помер у 1999 році.', '/memory/p206.jpg', 206, 204),
  ('Бублик Яків Павлович', null, 'Серед учнів і вчителів 5-й випуск 10-класників середньої школи у селі Шрамківка, Драбівський район, Черкаська область, 17.06.1941', '/memory/p207.jpg', 207, 205),
  ('Роде Григорій Харитонович', 'дідусь Сергія Роде, випускника 2001 р.', 'Народився в 1912 році на Житомирщині. В 1929 році закінчив педтехнікум. В 1930х жив і працював в Москві, вчився в Московському Енергетичному Інституті, служив строкову службу в армії. Воював на Халхінголі, на озері Хасан, артилерист-обчислювач. В 1941-1942 рр. сапер, обороняв Карелію, на тих ділянках фронту де виживав в середньому 1 з 4 чоловік. Контужений на початку 1942 року, місяць прожелав у госпіталі, нічого не чув і не бачив. Про війну згадувати не любив. З 1950х у Києві, енергетиком на радіозавіді, винахідник (понад 10 патентів, рацпропозиції і винаходи). Помер у 2009 році в Києві.', '/memory/p208.jpg', 208, 206),
  ('Гончаренко Михайло Васильович', 'прадід Сергія Роде, випуск 2001 р.', 'Народився в 1885 році у селі Княжичі на Броварщині, нащадок старих козацько-християнських родів краю. Учасник Першої світової війни, під час якої здобув професію ветеринарного фельдшера. Родина постраждала під час розкуркулення у 1920-1930х. Пережив голодовку 1932-1933 рр. В 1930х працював у колгоспі фельдшером. В 1941 році залишився в рідному селі, яке потрапило під окупацію. Розстріляний німцями при відступі у вересні 1943 року у рідному селі. За переказом це було зроблено, щоб не залишати Червоній Армії “живу силу”', '/memory/p209.jpg', 209, 207),
  ('Воло', 'сина Федір Никифорович – прадід Ігоря Хамази', 'Пішов на фронт з перших днів війни. У 1941-1943 роках захищав Воєнно- Грузинську дорогу у чині підполковника. Після війни жив і працював у місті Люботин Харківської області.', '/memory/p210.jpg', 210, 208),
  ('Нечипоренко Іван Іванович', 'прадід Ігоря Хамази', 'Народився в селі Домонтов під Києвом у селянській родині. У 1941 році пішов на фронт рядовим солдатом піхоти. Загинув у 1943 році в боях під Ленінградом. Під час війни був весь час на передовій.', '/memory/p211.jpg', 211, 209),
  ('Марачевич Микола Діонисович', 'прадід Ігоря Хамази', 'Герой Радянського Союзу. Командир 45-ї механізованої бригади 5-го механізованого корпусу 6-ї танкової армії 2-го Українського фронту, підполковник. Брав участь у боях з червня 1941 року. Відзначився при форсуванні річок Гірський Тикич, Південний Буг. За форсування Дністра нагороджений Орденом Леніна та медаллю «Золота зірка».', '/memory/p212.jpg', 212, 210),
  ('Сидорчук Іван Степанович', 'прадід Сучкова Валентина', 'Іван Степанович прожив важке і суворе життя – його батьки і сестри померли під час Голодомору. Виріс він у дитячому будинку. Потім була війна, поранення, інвалідність, але прадід залишився добрим, розумним і люблячим батьком для своїх семи дітей. Він пройшов славетну дорогу стежками Великої Вітчизняної війни з першого і до останнього дня, був розвідником і мав звання молодшого лейтенанта. За мужність і відвагу, проявлені в тяжких битвах під Сталінградом та на Курській Дузі, він був нагороджений Орденом Червоної Зірки та Орденами Слави, багатьма медалями. За всю війну був декілька разів тяжко поранений, та найважче поранення отримав в боях під Берліном.', '/memory/p213.jpg', 213, 211),
  ('Савост’ян Іван Савович', 'прадід Овчаренко Марії', 'В липні 1941 року був призваний до лав Радянської Армії. Загинув в перші місяці війни під Полтавою. Ешелон, в якому він їхав, потрапив під наліт німецької авіації.', '/memory/p214.jpg', 214, 212),
  ('Колісник Іван Федорович', 'прадід Марії Овчаренко', 'Був мобілізований у липні 1941 року. Брав участь в обороні Києва. Був снайпером у гвардійському полку. Отримав нагороди: медаль «За відвагу» та медаль «За перемогу над Німеччиною».', '/memory/p215.jpg', 215, 213),
  ('Танцура Людмила Семенівна', 'прабабуся Овчаренко Марії', 'Прабабуся Людмила , коли почалась війна навчалась в педагогічному інституті. І разом з інститутом була евакуйована в тил. Під час війни працювала на військовому заводі, який виробляв снаряди. (друга в першому ряді)', '/memory/p216.jpg', 216, 214),
  ('Мазніченко Володимир Мартинович', 'дідусь Мазніченко Анни', 'Старший сержант, командир взводу розвідки Першого Українського фронту. Учасник боїв за Дніпро, Польщу, Берлін, Прагу Винагороди: «За взяття Берліну»; «За звільнення Праги»; «За перемогу над Німеччиною». Був поранений. Деякий час вважався тим, що зник безвісті.', '/memory/p217.jpg', 217, 215),
  ('Колос Василь Степанович', 'дідусь Мазніченко Анни', 'У 1942-1943 роках був бійцем партизанського загону. З лютого 1944 року танкіст 282 окремого автотранспортного батальйону першої танкової армії. Нагороди: орден «Красной звезды» орден «Отечественной войны» 2 ст. Медалі: «За освобождение Варшавы» «За взятие Берлина» «За победу над Германией»', '/memory/p218.jpg', 218, 216),
  ('Данильчук Данило Федорович', 'прадід Вєдєнєєва В’ячеслава', 'Учасник партизанського руху в українському Поліссі. Нагороджений орденом Вітчизняної війни ІІ ступеня, медалями «Партизану Вітчизняної війни», «За перемогу над Німеччиною».', '/memory/p219.jpg', 219, 217),
  ('Мельник Іван Федорович', 'прадід Вєдєнєєва Вячеслава Іван Федорович загинув смертю', 'хоробрих у жовтні 1941 року під Москвою.', '/memory/p220.jpg', 220, 218),
  ('Частокол Макар Михайлович', 'дідусь Миколи Частокола', '1939-1941р.-участь у війні з Фінляндією. 1941-1945р.-участь у Великій Вітчизняній війні. Мав 5 поранень. Війну закінчив в Австрії в 1945р. Нагороджений медаллю “ За відвагу ”.', '/memory/p221.jpg', 221, 219),
  ('Гриценюк Їван Горгійович', 'прапрадід Шматка Андрія', 'Воював від початку Великої Вітчизняної війни. Був поранений 5 разів. Під командуванням генерала Рокосовського звільняв Київ, брав участь у його відбудові. Далі, починаючи від Житомирської області, звільняв Україну, Білорусь, Польщу, Чехословаччину і дійшов до Рейхстагу.', '/memory/p222.jpg', 222, 220),
  ('Сьомко Йосип Іванович', 'прадід Шматка Андрія', 'Пішов на фронт у 1941 році. Тримав оборону в бліндажах-точках, де фашисти і взяли в полон. Через 2 дні його відпустили, і відтоді був у партизанах. 7 січня 1944 року пішов у діючу армію, в частину, що розташовувалась тоді у Каменегірці. Служив в колишній Шумській 246-ій дивізії 908-го стрілецького На фронті, який проходив тоді біля села Швайківка, стояли в обороні три з половиною місяці, а 13 липня 1944 року пішли в наступ, прорвавши оборону. Загинув 3 серпня 1944 року, в районі Кракова і Жешова, внаслідок трьох кульових поранень в голову.', '/memory/p223.jpg', 223, 221),
  ('Орлов Олексій Олександрович', 'дідусь Малиновської Олександри', 'Народився в 1924 році. З липня 1942 після закінчення середньої школи – на фронті. Служив матросом на торпедних катерах Балтійського флоту. Брав участь у звільненні Ленінграда від фашистської блокади. Нагороджений медаллю «За оборону Ленинграда», «За боевые заслуги», «За отвагу», орденом «Красной звезды» та іншими, був поранений. Після війни закінчив військовоморське училище, служив на Північному флоті, капітан І рангу.', '/memory/p224.jpg', 224, 222),
  ('Роганов В’ячеслав Михайлович', 'дідусь Роганової Антоніни', 'На фронті з 22 червня 1941 и до дня Перемоги. Учасник битви на Курській дузі, боїв за визволення Праги.', '/memory/p225.jpg', 225, 223),
  ('Нікітін Іван Олексійович (1918', '1982) – прадід Антона Дровальова', 'Народився 5 січня 1918 в місті Мічуринске. Закінчив Московське училище НКВС. Воював в Одесі, Севастополі. У боях за Керч отримав поранення. Все життя прожив з осколком у легенях. Після лікування у госпіталі брав участь у визволенні України, дійшов до Чехословаччини. Служив у військах зв''язку. Війну закінчив капітаном, після війни продовжував службу у 145 полку в Кам''янці-Подільському. Нагороджений медалями “За оборону Севастополя”, “За оборону Одеси”, “За оборону Кавказу”, орденом Червоної Зірки.', '/memory/p226.jpg', 226, 224),
  ('Богданівський Микола Якович', 'прадід Віктора Лежнєва', 'Підполковник медслужби. Нагороджений орденом Червоної Зірки', '/memory/p227.jpg', 227, 225),
  ('Палкіна Таїсія Миколаївна', 'прабабуся Віктора Лежнєва Пройшла всю війну, була', 'медсестрою', '/memory/p228.jpg', 228, 226),
  ('Лісняк Микита (1903', '1956) – прадід Агулова Андрія', 'У 1942 році, під час окупації села Синяви Рокитнянського району Київської області, де проживав Микита Лісняк, багатьох селян забрали на примусові роботи до Німеччини. Ця доля не минула і мого прадіда. В Німеччині “остарбайтери” жили в жахливих умовах, погано харчувалися та важко працювали. В 1944 році Радянська армія визволила полонених, а серед них і Микиту. Він воював до кінця війни, дійшов до Берліну. Працював поваром. Одного разу бомба влучила у його польову кухню, вона розлетілась вщент, але Микита не постраждав. Після війни він повернувся до рідного села і працював лісничим.', '/memory/p229.jpg', 229, 227),
  ('Мартиненко Петро Мойсейович', 'батько', 'вчителя Рустамової В.П., прадід Стеч Жанни Петро Мойсейович народився 6 серпня 1916 року у Донецькій області в селі Луганське Артемівського району. Військове звання – старшина. Призваний на дійсну воєнну службу 6 вересня 1939, службу проходив на Далекому Сході. З червня 1941 року по травень 1945 року у складі 413 автотранспортного батальйону, 42 відділення брав участь у боях на фронтах Великої Вітчизняної війни. З серпня 1945 року по вересень 1945 року воював з Японією, демобілізований 6 червня 1946 року. Нагороджений Орденом Отечественной войны, Орденом «За мужність», медалями «За отвагу», «За победу над Японией» Помер 3 травня 2009р., похований у Києві', '/memory/p230.jpg', 230, 228),
  ('Мартиненко Геннадій Мойсейовіч', 'дядько', 'вчителя В.П.Рустамової, прадід Стеч Жанни Народився у 1919 році. Призваний на дійсну військову службу в 1940 році. Воював з 1941 по 1944 рік. У 1944 році комісований через поранення. Нагороджений Орденом Вітчизняної війни, медаллю «За відвагу», «За мужність» Помер у 1999 році.', '/memory/p231.jpg', 231, 229),
  ('Андрійченко Микола Іларіонович (1902', '1985) - прадід Кравченко Миколи', 'Андрійченко М.І. брав участь у Сталінградської битві в складі 1058-го артилерійського полку. Битва була дуже важкою і кровопролитною. Гармата, якою командував Микола Іларіонович, тільки в одному бою знищила 13 німецьких танків. В тих боях старшина Андрійченко М.І. був важко поранений. Після Сталінградської битви Микола Іларіонович пройшов славетний бойовий шлях – брав участь у Курській битві, визволяв від німецько-фашистських загарбників Київ, Україну, Польщу, дійшов до Берліна, де зустрів Перемогу. За свої воїнські подвиги він був нагороджений багатьма бойовими орденами та медалями. Після війни працював головним агрономом Александрійського району Кіровоградської області. За трудові досягнення був нагороджений високими трудовими орденами.', '/memory/p232.jpg', 232, 230),
  ('Трикуш Павло Якович (1923', '1996) – прадід Троцько Христини', 'Павло Якович Трикуш народився 22 березня 1923 року в селі Линев Локачинського району Волинської області. Наприкінці 1943 року був призваний до лав Радянської Червоної Армії і боровся за Батьківщину в 526 стрілецькому полку 89 стрілецької Таманської Дивізії . Був розвідником. За хоробрість, стійкість, мужність, за зразкове виконання бойових завдань на фронті боротьби з німецькими окупантами нагороджений Орденом Вітчизняної війни I ступеня, Орденом Червоної Зірки; медалями «За відвагу , «За взяття Берліна», «За перемогу над Німеччиною У ВЕЛИКІЙ ВІТЧИЗНЯНІЙ ВІЙНІ 1941-1945 рр. .» та ін. Червоноармієць Трикуш Павло Якович брав участь у героїчному штурмі і взятті столиці фашистської Німеччини - Берліна. При форсуванні річки Одер він був важко поранений у праву частину грудної клітки. І тільки лише наприкінці листопада 1945 після тривалого лікування повернувся додому. Після цього виростив і виховав сина та доньку. Пішов з життя 18 листопада 1996 року. Сьогодні світлу пам''ять про своє героїчне дідусеві несуть троє його онуків і вже четверо правнуків.', '/memory/p233.jpg', 233, 231),
  ('Завітневич Володимир Порфирійович', 'прадід Горняк Ольги та Ксенії', 'До війни мешкав в Архангельську. У діючу армію був призваний в серпні 1942 року. Служив в артилерійському полку, ходив у розвідку. У 1943 році брав участь у прориві блокади Ленінграда, отримав медаль “За бойові заслуги” У 1944 воював на 2 Прибалтійському фронті, за бойові заслуги отримав медаль. У 1945 у складі воїнських частин Українського фронту воював у Румунії, де і закінчив війну.', '/memory/p234.jpg', 234, 232),
  ('Литвиненко Іван Кирилович (1915', '2007) – прадід Литвиненко Микити', 'Мобілізований до Радянської армії 7 липня 1941 року. 7 жовтня його батальйон, попри мужню відсіч, був оточений і потрапив у полон. З неволі він спромігся втекти. Провівши багато місяців у скитаннях, Іван Кирилович повернувся додому. 14 січня 1944 року був повторно мобілізований до Червоної армії. Продовжуючи службу, він воював на Білоруському фронті, брав участь у звільненні Польщі. У місті Гданськ, на берегах Балтійського моря, Іван Кирилович і зустрів перемогу. За відмінні бойові дії Іван Кирилович нагороджений орденом Червоної зірки, 2-ма медалями «За Відвагу», медаллю за звільнення Варшави, отримав 2 подяки за звільнення міст Картхауза і Гданська. 22 травня 1946 року був демобілізований.', '/memory/p235.jpg', 235, 233),
  ('Кудокодцев Спиридон Іванович (1918', '2009)', 'У 1943 році добровільно пішов на фронт, воював у складі 98 стрілецької дивізії. Брав участь у визволенні м. Мелітополь, форсував річки Дніпро, Одер, звільняв Польщу, Чехословаччину. Війну закінчив на півдні Німеччини в Баварії. Демобілізувався за Указом Президії Верховної Ради СРСР 25 вересня 1945 року.', '/memory/p236.jpg', 236, 234),
  ('Пшегорницька Антоніна Тимофіївна', 'бабуся Ксенії Крамар', 'Моя бабуся народилася 16 квітня 1939 року. Коли почалась війна, їй було всього 3 роки. Незважаючи на такий малий вік, жорсткі події війни залишилися в її пам’яті назавжди. ЇЇ батько загинув на фронті. Бабуся майже його не пам’тає, тому їй завжди важко говорити про це. Із 5 її сестер живою залишилася лише вона одна. Війна не жаліла нікого - ні старих, ні молодих. Кожній родині вона нанесла смертельні рани. Бережіть мир, який дістався нашими рідними такою важкою ціною. Завжди пам’ятайте тих, хто завоював цю Велику Перемогу', '/memory/p237.jpg', 237, 235),
  ('Борисенко Діна Арсентіївна (1924', '2011) – бабуся Борисенко Єлізавети', 'Війна застала Діну Павличенко студенткою медучилища в 17 років. Пішла на фронт медсестрою, виносила поранених з поля бою, сама була поранена осколками снаряда. В якості сержанта медичної служби брала участь у визволенні міст Біла Церква, Могилів Подільський та інших, у звільненні Трансільванії, в ліквідації Корсунь Шевченківської та Уманської угруповань німців, у форсуванні річки Дністер, в утриманні плацдарму на західному березі Дунаю. Нагороджена орденом Вітчизняної війни 2 ступеня і медаллю «За відвагу»', '/memory/p238.jpg', 238, 236),
  ('Головаш Софія Андріївна та Андрій Платонович (1903 – 1986)', 'бабуся та дідусь Борисенко Єлізавети', 'Софія Андріївна народилася 22 липня 1926 року Підлітком потрапила на війну, разом з матір''ю Вірою Миколаївною працювала на військово - польовій кухні. У складі діючої армії дійшла до Берліна, в дні Перемоги разом з іншими солдатами розписалася на стінах Рейхстагу. Нагороджена численними медалями, в тому числі медаллю «За перемогу над Німеччиною». Андрій Платонович у складі 1 Білоруського фронту під командуванням генерала К.К. Рокоссовського брав участь у визволенні Білорусії, Польщі, в битві за Берлін. Був поранений і після війни отримав інвалідність 1 групи. Нагороджений двома орденами Вітчизняної війни, двома орденами Червоної Зірки і численними медалями, в тому числі медалями «За взяття Берліна» та «За бойові заслуги».', '/memory/p239.jpg', 239, 237),
  ('Євсейцев Григорій Іванович', 'прадід Андрія Євсейцева(??? - 1978)', 'Григорій Іванович був на війні з самого початку, Перемогу зустрів у Берліні. Був військовим розвідником. Кавалер 3-х орденів Слави.', '/memory/p240.jpg', 240, 238),
  ('Сковпень Стефан Антонович', 'прадід Скиби Андрія', 'Загинув у боях на підступах до Ленінграду 5 квітня 1942 року. Вважався як такий, що пропав без вісті. Місце поховання (братська могила в лісі) знайдене після публікації Узагальненого банку даних громадської організації «Меморіал».', '/memory/p241.jpg', 241, 239),
  ('Цвінарія Костянтин', 'дідусь Микити Дячкова', 'Закінчив Київське кавалерійське училище, кінний зв’ язківець. Учасник оборони Києва. Помер на початку 80-х років внаслідок поранення.', '/memory/p242.jpg', 242, 240),
  ('Шилков Андрій Максимович', 'прадід Шилкової Марини Під час війни був начальником', 'парашутно-десантної служби ВПС. Андрій Максимович готував парашутистівдесантників, яких закидали в тил ворога. Сам багато разів у складі таких груп брав участь в бойових операціях в тилу ворога. Доставляв вантажі нашим партизанам. Нагороджений орденом Леніна, двома орденами Червоного прапора, двома орденами Червоної зірки.', '/memory/p243.jpg', 243, 241),
  ('Хазин Авраам Мотелевич', 'прадід Байкових Михайла та Катерини Воював на ІІІ Українському', 'фронті. Був начальником тилу танкової бригади', '/memory/p244.jpg', 244, 242),
  ('Короткий Валентин Михайлович', 'прадід Короткої Дарії', 'Валентин Михайлович зустрів Велику Вітчизняну війну курсантом військового училища. Протягом війни брав участь у військових діях Прибалтійського фронту, був військовим розвідником, безпосередньо звільняв Варшаву .', '/memory/p245.jpg', 245, 243),
  ('Короткий Валентин Михайлович', 'прадід Короткої Дарії За бойові заслуги був нагороджений:', 'орденами: Олександра Невського, Великої Вітчизняної війни 2-ї ступені, двома орденами Червоної Зірки. Під час розвідувальних операцій був поранений два рази. Війну закінчив у 1944 році. Брав участь у параді Перемоги 1945 року.', '/memory/p246.jpg', 246, 244),
  ('Гороховский Григорий Израилевич', 'прадід Гороховського Івана', 'Народився 15 грудня 1924 року в Астрахані. На початку війни був студентом . Пережив блокаду в Ленінграді, був бійцем винищувального батальйону. У 1942 році призваний в діючу армію. Був командиром шабельної роти, командиром мінометного взводу. У 1944 визволяв Західну Україну. Після війни служив у десантних військах. Нагороджений багатьма медалями і орденами, в їх числі: медаль « За оборону Ленінграда», медаль « За військові заслуги» , два ордени «Великої вітчизняної війни »', '/memory/p247.jpg', 247, 245),
  ('Дьомін Ісак Львович (1922', '1943) – дідусь Дьоміна Олексія', 'У 1940-му році був призваний на службу в Червону Армію. Зустрів війну на Західній Україні під містом Рівне. Всі три роки воював зв''язківцем у піхоті. А в листопаді 1943р. рідні отримали сповіщення про те, що рядовий Дьомін І. Л. пропав безвісти ...', '/memory/p248.jpg', 248, 246),
  ('Сапун Василь Степанович (1925', '2005) – дідусь Дьоміна Олексія', 'Уродженець Полтавщини. Через польовий військкомат 18-річний юнак добровільно пішов на фронт. У 1943 - 1945 роках брав безпосередню участь у боях на 3-му Українському фронті рядовим солдатом – артилеристом. Воював під Харковом і Києвом , в районі Ясс і в Угорщині. В одному з тяжких боїв в Угорщині, в районі озера Балатон був важко контужений, після семи місяців лікування в госпіталях був демобілізований. Василь Степанович має бойові нагороди: орден Слави 1 ступені, орден Вітчизняної війни 1 і 2 ступені, багато медалей.', '/memory/p249.jpg', 249, 247),
  ('Михайло Колос', 'дідусь Жданових Арсенія і Ярини', 'Рядовим червоноармійцем дійшов до Берлину Учасник звільнення Ковеля, Варшави, Праги, Шпандаута, Берліну', '/memory/p250.jpg', 250, 248),
  ('Яків Круковський', 'дідусь Жданових Арсенія і Ярини', 'До війни був істориком. Загинув у березні 1944 в с. Марківці на березі Південного Бугу під час ПроскуровоЧерновецької наступальної операції.', '/memory/p251.jpg', 251, 249),
  ('Гардюта Олег Гнатович', 'дідусь Редчуків Марії та Олега', 'Народився в м.Кіровограді. У 1943 році добровільно записався у артполк, став розвідником-спостерігачем. У Польщі за допомогу в розгромі гітлерівців отримав орден «За відвагу». Дійшов до Кенігсберга. Війну закінчив, маючи звання молодшого сержанта та бойові нагороди: орден Червоного прапора, медалі «За відвагу», «За взяття Кенігсберга». Демобілізувався 1947 року. Має 30 років трудового стажу.', '/memory/p252.jpg', 252, 250),
  ('Гардюта Тамара Миколаївна', 'бабуся Редчуків Марії та Олега', 'Народилась у м.Кострома (Росія). У 16 років зустріла війну. Під час війни працювала на військовому заводі, виготовляла бомби. Працювали майже цілодобово, спали та відпочивали у цеху. Нині на заслуженому відпочинку, живе у Росії.', '/memory/p253.jpg', 253, 251),
  ('Лернер Юхим Ілліч (1913', '2006 р.) – дідусь Чаплигіна Костянтина', 'Пішов на фронт 22 червня 1941 року. Закінчив війну під Калінінградом у 1945 році у званні старшого лейтенанта. Служив у інженерних військах, був поранений. Має нагороди: «Орден Червоної Зірки» «Орден Червоного Прапора» Медаль «За Відвагу» Медаль «За взяття Кенігсберга» «Орден Великої Вітчизняної Війни» 1 і 2 ступеня Медаль «За бойові заслуги»', '/memory/p254.jpg', 254, 252),
  ('Журавльов Микола Тимофійович (1912', '1990) - прадід Різаєва Євгена', 'Народився у 1912 році у м. Чистякові Донецької області. До початку Другої світової війни працював шахтарем у м. Шахтарську. Під час війни Микола Тимофійович був розвідником, через що його дружина потерпала від катувань гестапівців. Був нагороджений багатьма орденами. Микола Тимофійович брав участь у визволенні Донецька у 1943, а після визволення Донецької області від німецької окупації залишився у Шахтарську, де відновлював шахти. На його честь названий мікрорайон цього міста - Журавльовка. Після війни працював директором, пізніше – заступником директора шахти у Шахтарську.', '/memory/p255.jpg', 255, 253),
  ('Слінченко Герасим Пилипович', 'прадід Майї Одноволик', 'У 1941 р. був призваний до лав діючої армії. Разом з багатьма військовими потрапив у київський котел і став військовополоненим. Табір військовополонених знаходився в Дарниці. З цього табору він втік і до приходу Радянської армії перебував на тимчасово окупованій території, на Донбасі, до 1943р. З приходом Червоної армії прийшов до відповідної частини, де пояснив свою тривалу відсутність і пройшов відповідну перевірку смершев. До речі, ще у 1941р. сім''я одержала повідомлення, що Слінченко Герасим пропав без вісті. Продовжував бойовий шлях з Донбасу з 1943р. до звільнення Праги у 1945р. І це все пішки (між боями) та іншими способами пересування під час боїв, при цьому треба було розмотувати та змотувати телефонні дроти між бойовими частинами. Брав участь у форсуванні Дніпра та інших водних перешкод. Мав штикове поранення у рукопашному бою, був контужений. За час бойових дій нагороджений орденом Червоної зірки та медаллю «За відвагу», почесними Грамотами Верховного головнокомандувача. Як учасник бойових дій у 1995р. нагороджений орденом "Вітчизняної війни" 2-го ступеня та ювілейними військовими медалями.', '/memory/p256.jpg', 256, 254),
  ('Линник Федір Герасимович (1905', '1942) - прадід Антона Главіна', 'Спочатку його військова частина била фашистів під Одесою. Потім отримали наказ піти на захист Севастополя. Билися до останнього патрона - з берданками проти кулеметів і автоматів. Їх відтіснили до Херсонесу, який представляв із себе суцільну масу людей, не здатних вже чинити опір, але фашисти продовжували бомбити, перетворюючи їх на криваву масу. Федір Герасимович вижив і тут, з боєм пішов з Херсонеса і ще два тижні продовжував битися після здачі міста. Родина чекала його до наших днів, чекала, незважаючи на похоронку від 12.VI. 1942р. А він всупереч похоронці дійсно був ще живий до кінця грудня 1942р., поки не був замучений каторжною працею, голодом, холодом і побоями у концтаборі "Lamsdorf" у Польщі . Коли він помер, йому було тільки 37 років ...', '/memory/p257.jpg', 257, 255),
  ('Чепинога Ольга Петрівна (1907', '1983), Шейнкман Еммануїл Абрамович (1908-1942) - прабабуся і прадід Антона Главіна', 'На фотографії - Ольга Петрівна і Еммануїл Абрамович в день закінчення санітарно-гігієнічного факультету Київського медінституту. Працювали до війни дослідникамибиохимиками, обидва були на фронті. Еммануїл Абрамович пішов на війну добровольцем в перші ж її дні, був лікарем фронтового госпіталю. Загинув в оточенні під Харковом. Ольга Петрівна також була лікарем госпіталю, спочатку евакуаційного, потім і фронтового. Як і її чоловік, побувала в оточенні, на Кавказі, з якого, проте, вдалося вийти.', '/memory/p258.jpg', 258, 256)
) as seed(name, relation, biography, photo_url, source_page, sort_order)
where not exists (select 1 from public.memory_entries);
